/* ===== ARYAN admin panel ===== */
const A={token:store.get('aryan_admin_token')||'',me:null,route:'dashboard',cfg:null,lp:{},items:{}};
const api=makeApi(()=>A.token,()=>{if(A.me){A.token='';store.del('aryan_admin_token');A.me=null;showLogin();toast('Session expired. Login again.','err')}});
const root=$('#root');
const can=(p)=>{if(!p)return true;const x=(A.me&&A.me.permissions)||[];return x.includes('*')||x.includes(p)||(p.includes('.')&&x.includes(p.split('.')[0]))};
const NAV=[['Overview',[['dashboard','home','Dashboard','dashboard']]],
['Customers',[['users','users','Users','users.read'],['orders','receipt','Orders','orders'],['transactions','list','Transactions','transactions'],['wallets','wallet','Wallet Mgmt','wallet.read'],['balance','dollar','Add / Deduct Balance','wallet'],['tickets','lifebuoy','Support Tickets','tickets']]],
['Catalog',[['products','package','Products','products'],['pids','hash','PID Management','products'],['prices','tag','Price Mgmt','products'],['durations','clock','Duration Mgmt','products'],['stock','key','Key Stock','stock'],['videos','video','Product Videos','media']]],
['Integrations',[['suppliers','server','Supplier Panels','suppliers'],['gateways','zap','Payment Gateways','gateways'],['apiclients','code','API Management','api'],['apidocs','book','API Documentation',null],['apilogs','activity','API Request Logs','api'],['telegram','send','Telegram Bot','telegram']]],
['Site',[['media','image','Media Manager','media'],['branding','palette','Website Branding','branding'],['announcements','megaphone','Announcements','announcements'],['maintenance','tool','Maintenance Mode','maintenance']]],
['System',[['settings','settings','Admin Settings','settings'],['security','shield','Security Settings','security']]]];
const ALLR=NAV.flatMap(g=>g[1]);
const money=inr;const dtxt=fdate;
const spin=()=>`<div class="view">${skelRows(5,56)}</div>`;

/* ---------- login ---------- */
function showLogin(){root.innerHTML=`<div id="login"><div class="auth-box"><div class="ta-c" style="margin-bottom:22px"><div style="display:inline-block"><div class="brand"><div class="mark">${logoMark(A.brand)}</div><div><b>ARYAN</b><small>Admin Console</small></div></div></div></div><form class="card col" id="loginForm"><h2 style="font-size:20px">Admin sign in</h2><div class="field"><label>Email</label><div class="input-wrap">${ico('mail')}<input class="input" id="lem" type="email" autocomplete="username" required></div></div><div class="field"><label>Password</label><div class="input-wrap">${ico('lock')}<input class="input" id="lpw" type="password" autocomplete="current-password" required>${pwToggle('lpw')}</div></div><button class="btn primary block" type="submit">Sign in</button><div class="hint">Access is limited to authorised admins. All actions are audit-logged.</div></form></div></div>`}
document.addEventListener('submit',async e=>{if(e.target.id!=='loginForm')return;e.preventDefault();const b=$('button[type=submit]',e.target);await withBusy(b,async()=>{try{const r=await api('POST','/api/admin/login',{email:$('#lem').value.trim(),password:$('#lpw').value});A.token=r.token;store.set('aryan_admin_token',r.token);A.me={...r.admin};start()}catch(er){toast(er.message,'err',6000)}})});

/* ---------- shell ---------- */
async function boot(){const ai=parseInt(store.get('aryan_accent')||'0',10);applyAccent(isNaN(ai)?0:ai);try{const c=await api('GET','/api/public/config');A.brand=c.brand;A.cfg=c;applyBrand(c.brand)}catch{}
  if(A.token){try{const r=await api('GET','/api/admin/me',undefined,{noAuthRedirect:true});A.me=r.admin;return start()}catch(e){A.token='';store.del('aryan_admin_token')}}showLogin()}
function start(){
  root.innerHTML=`<div id="app"><aside id="side"><div style="padding:6px 8px 12px"><div class="brand"><div class="mark">${logoMark(A.brand)}</div><div><b>${esc(((A.brand&&A.brand.siteName)||'ARYAN').toUpperCase())}</b><small>Admin</small></div></div></div><nav class="nav">${NAV.map(g=>{const it=g[1].filter(x=>can(x[3]));return it.length?`<h6>${g[0]}</h6>`+it.map(x=>`<a href="#/${x[0]}" data-r="${x[0]}">${ico(x[1])}<span>${x[2]}</span></a>`).join(''):''}).join('')}<div style="flex:1"></div><button data-act="logout">${ico('logout')}<span>Logout</span></button></nav></aside><div id="scrim" data-act="closeNav"></div><div id="main"><header id="top"><button class="btn icon ghost" data-act="openNav" aria-label="Menu">${ico('menu','lg')}</button><div class="sp"></div><a class="btn sm ghost" href="/" target="_blank" rel="noopener">${ico('ext','sm')} <span class="hide-xs">User site</span></a><button class="btn icon ghost" data-act="accent" aria-label="Theme colour">${ico('palette','lg')}</button><span class="badge info">${esc(A.me.role)}</span><span class="muted fs12 hide-xs trunc" style="max-width:200px">${esc(A.me.email)}</span></header><main id="content"></main></div></div>`;
  window.addEventListener('hashchange',route);route()}
async function route(){let r=(location.hash.replace(/^#\//,'')||'dashboard').split('?')[0];const def=ALLR.find(x=>x[0]===r);if(!def||!can(def[3])){r=(ALLR.find(x=>can(x[3]))||['dashboard'])[0]}A.route=r;
  $$('[data-r]').forEach(a=>a.classList.toggle('on',a.dataset.r===r));$('#side').classList.remove('open');$('#scrim').classList.remove('show');const c=$('#content');c.innerHTML=spin();window.scrollTo(0,0);
  try{await V[r](c)}catch(e){c.innerHTML=`<div class="alert err">${ico('alert')}<div>${esc(e.message)}</div></div><button class="btn" style="margin-top:12px" data-act="reload">Retry</button>`}}
const head=(t,sub,right='')=>`<div class="page-h"><h2>${t}</h2><div class="sp"></div>${right}${sub?`<p>${sub}</p>`:''}</div>`;
const rerender=()=>route();

/* ---------- helpers ---------- */
function fld(id,label,val='',o={}){const t=o.type||'text',h=o.hint?`<div class="hint">${o.hint}</div>`:'';let inp;
  if(t==='select')inp=`<select class="input" data-f="${id}" id="f_${id}">${o.opts.map(x=>{const v=Array.isArray(x)?x[0]:x,l=Array.isArray(x)?x[1]:x;return `<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`;
  else if(t==='textarea')inp=`<textarea class="input" data-f="${id}" id="f_${id}" ${o.ph?`placeholder="${esc(o.ph)}"`:''} rows="${o.rows||3}">${esc(val)}</textarea>`;
  else if(t==='check')return `<label class="chk" style="border:0"><span class="switch"><input type="checkbox" data-f="${id}" id="f_${id}" ${val?'checked':''}><span></span></span><span class="fw6">${label}</span>${h}</label>`;
  else inp=`<input class="input" data-f="${id}" id="f_${id}" type="${t}" value="${esc(val)}" ${o.ph?`placeholder="${esc(o.ph)}"`:''} ${o.req?'required':''} ${o.step?`step="${o.step}"`:''} ${o.min!=null?`min="${o.min}"`:''} autocomplete="off">`;
  return `<div class="field" ${o.span?`style="grid-column:1/-1"`:''}><label for="f_${id}">${label}</label>${inp}${h}</div>`}
function readF(el){const o={};$$('[data-f]',el).forEach(i=>{o[i.dataset.f]=i.type==='checkbox'?i.checked:i.value});return o}
const badges=(s)=>statusBadge(s);
const attrs=(l)=>l;
function table(cols,rows,{empty='No records found'}={}){if(!rows.length)return `<div class="card">${emptyBox('list',empty)}</div>`;return `<div class="tbl-wrap"><table class="tbl rsp"><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td data-l="${esc(String(cols[i]||'').replace(/<[^>]*>/g,''))}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
const pager=(r,key)=>r.total>r.size?`<div class="pager"><span class="muted fs12">${(r.page-1)*r.size+1}–${Math.min(r.total,r.page*r.size)} of ${r.total}</span><button class="btn sm" data-act="pg" data-k="${key}" data-d="-1" ${r.page<=1?'disabled':''}>Prev</button><button class="btn sm" data-act="pg" data-k="${key}" data-d="1" ${r.page*r.size>=r.total?'disabled':''}>Next</button></div>`:'';
function qs(o){return Object.entries(o).filter(([,v])=>v!==''&&v!=null).map(([k,v])=>`${k}=${encodeURIComponent(v)}`).join('&')}
/** generic paginated list page */
async function listPage(c,k,cfg){const st=A.lp[k]||(A.lp[k]={q:'',page:1,f:{}});const paint=async()=>{const body=$('#lp_body');body.innerHTML=skelRows(4,52);try{const r=await api('GET',`${cfg.path}?${qs({q:st.q,page:st.page,size:cfg.size||25,...st.f})}`);A.items[k]=r.items;st.last=r;body.innerHTML=(cfg.summary?`<div class="sumbar">${cfg.summary(r)}</div>`:'')+table(cfg.cols,r.items.map((it,i)=>cfg.row(it,i)),{empty:cfg.empty})+pager(r,k)}catch(e){body.innerHTML=`<div class="alert err">${ico('alert')}<div>${esc(e.message)}</div></div>`}};
  c.innerHTML=`<div class="view">${head(cfg.title,cfg.sub||'',cfg.right||'')}<div class="fbar">${cfg.search!==false?`<div class="input-wrap grow">${ico('search')}<input class="input" id="lp_q" placeholder="${esc(cfg.ph||'Search…')}" value="${esc(st.q)}"></div>`:''}${(cfg.filters||[]).map(f=>`<select class="input" data-lpf="${f.k}"><option value="">${f.label}</option>${f.opts.map(o=>`<option ${st.f[f.k]===o?'selected':''}>${o}</option>`).join('')}</select>`).join('')}<button class="btn icon" data-act="lpRefresh" aria-label="Refresh">${ico('refresh')}</button></div><div id="lp_body"></div></div>`;
  A.lpPaint=paint;A.lpK=k;const q=$('#lp_q');if(q)q.addEventListener('input',debounce(()=>{st.q=q.value;st.page=1;paint()},300));$$('[data-lpf]',c).forEach(s=>s.addEventListener('change',()=>{st.f[s.dataset.lpf]=s.value;st.page=1;paint()}));await paint()}
const mini=(t)=>`<span class="mono fs12">${esc(t)}</span>`;
const abtn=(act,label,icon,cls='',data={})=>`<button class="btn sm ${cls}" data-act="${act}" ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${icon?ico(icon,'sm'):''}${label?' '+label:''}</button>`;
async function askPw(msg='Enter your admin password to continue.'){return new Promise(res=>{const m=modal(`<p class="muted fs13" style="margin-bottom:10px">${msg}</p><div class="input-wrap">${ico('lock')}<input class="input" type="password" id="apw" autocomplete="current-password"></div>`,{title:'Confirm password',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-ok>Confirm</button>',onClose:()=>res(null)});const go=()=>{const v=m.$('#apw').value;if(!v)return;res(v);m.ov.remove()};m.ov.addEventListener('click',e=>{if(e.target.closest('[data-ok]'))go()});m.ov.addEventListener('keydown',e=>{if(e.key==='Enter')go()})})}
const secretModal=(title,rows)=>modal(rows.map(r=>`<div class="field" style="margin-bottom:10px"><label>${esc(r[0])}</label><div class="keybox"><span>${esc(r[1]||'(not set)')}</span>${r[1]?`<button class="btn icon sm" data-copy="${esc(r[1])}">${ico('copy','sm')}</button>`:''}</div></div>`).join('')+'<div class="hint">This reveal was written to the audit log.</div>',{title,footer:'<button class="btn primary" data-close>Close</button>'});
const fmtJ=(o)=>JSON.stringify(o,null,2);
const V={};
const ACT={};
const done=(m)=>toast(m||'Saved','ok');
const reload=()=>rerender();
const itm=(el)=>A.items[el.dataset.k][+el.dataset.i];
const rowBtns=(k,i,list)=>`<div class="row gap6 wrap" style="justify-content:flex-end">${list.map(([a,l,ic,cl])=>abtn(a,l,ic,cl,{k,i})).join('')}</div>`;

/* ================= Dashboard ================= */
V.dashboard=async(c)=>{const d=await api('GET','/api/admin/dashboard');const mx=Math.max(1,...d.series.map(s=>s.sales));
  const T=(l,v,s,ic)=>`<div class="card stat hover"><div class="lbl">${ico(ic,'sm')} ${l}</div><div class="val">${v}</div><div class="sub">${s}</div></div>`;
  c.innerHTML=`<div class="view">${head('Dashboard','Live data straight from your database — nothing here is simulated')}<div class="grid g4 keep2" style="margin-bottom:14px">${T('Users',d.users.total,`${d.users.resellers} resellers • ${d.users.banned} banned`,'users')}${T('Wallet total',money(d.users.walletTotal),'All user balances','wallet')}${T('Sales',money(d.money.sales),`Cost ${money(d.money.supplierCost)}`,'dollar')}${T('Profit',money(d.money.profit),'Sales − supplier cost','trend')}${T('Orders',d.orders.total,`${d.orders.delivered} delivered • ${d.orders.failed} failed • ${d.orders.review} review`,'receipt')}${T('Products',d.products.total,`${d.products.plans} plans • ${d.products.inactive} inactive`,'package')}${T('Payments',money(d.payments.amountReceived),`${d.payments.success} ok • ${d.payments.pending} pending • ${d.payments.review} review`,'zap')}${T('API',d.api.requestsToday,`today • ${d.api.requestsTotal} total • ${d.api.clients} keys`,'code')}</div>
  <div class="grid g2" style="margin-bottom:14px"><div class="card"><div class="card-h">${ico('chart')}<h3>Sales — last 14 days</h3></div><div class="bars">${d.series.map(s=>`<div style="height:${Math.max(3,s.sales/mx*100)}%" data-tip="${esc(s.d)}: ${money(s.sales)} • ${s.orders} orders"></div>`).join('')}</div><div class="bar-lbls">${d.series.map((s,i)=>`<span>${i%2?'':s.d.slice(3)}</span>`).join('')}</div></div>
  <div class="card"><div class="card-h">${ico('server')}<h3>Connections</h3></div>${[...d.gateways.map(g=>['Gateway',g]),...d.suppliers.map(s=>['Supplier',s])].map(([t,g])=>`<div class="row" style="padding:8px 0;border-bottom:1px solid var(--border)"><span class="dot ${g.status==='ok'?'ok':g.status==='error'?'err':'warn'}"></span><b class="sp trunc">${esc(g.name)}</b><span class="badge">${t}</span>${statusBadge(g.enabled?(g.status==='ok'?'CONNECTED':g.status):'INACTIVE')}</div>`).join('')||emptyBox('server','No gateways or suppliers configured yet')}</div></div>
  <div class="card"><div class="card-h">${ico('receipt')}<h3>Recent orders</h3></div>${table(['Order','User','Product','PID','Duration','Total','Status','Date'],d.recent.map(o=>[mini(o.id),esc(o.username),esc(o.product),`<span class="pid">${esc(o.pid)}</span>`,esc(o.duration),money(o.total),statusBadge(o.status),`<span class="muted fs12">${dtxt(o.ts)}</span>`]),{empty:'No orders yet'})}</div></div>`};

/* ================= Users ================= */
V.users=(c)=>listPage(c,'users',{title:'Users',path:'/api/admin/users',ph:'Search username, email, UID…',filters:[{k:'role',label:'All roles',opts:['User','Reseller']}],cols:['User','Email','Role','Balance','Keys','Status','Joined',''],
  row:(u,i)=>[`<b>${esc(u.username)}</b><div class="muted fs12">${esc(u.name)}</div>`,esc(u.email),statusBadge(u.role),money(u.balance),u.keys,u.banned?statusBadge('BANNED'):statusBadge('ACTIVE'),`<span class="muted fs12">${dtxt(u.joinedAt)}</span>`,rowBtns('users',i,[['userEdit','','edit'],['userBal','','wallet'],['userReset','','key'],['userDel','','trash','danger']])]});
ACT.userEdit=(el)=>{const u=itm(el);const m=modal(`<div class="fgrid">${fld('name','Name',u.name)}${fld('role','Role',u.role,{type:'select',opts:['User','Reseller']})}${fld('banned','Banned (cannot login or buy)',u.banned,{type:'check'})}</div><div class="hint" style="margin-top:8px">UID: <span class="mono">${esc(u.uid)}</span></div>`,{title:'Edit '+esc(u.username),footer:`<button class="btn" data-act="userLogout" data-uid="${esc(u.uid)}">Force logout</button><button class="btn primary" data-sv>Save</button>`});
  m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{await api('PATCH','/api/admin/users/'+encodeURIComponent(u.uid),readF(m.el));m.close();done();A.lpPaint()}catch(er){toast(er.message,'err')}})})};
ACT.userLogout=async(el)=>{await api('POST',`/api/admin/users/${encodeURIComponent(el.dataset.uid)}/logout`);done('User logged out everywhere')};
ACT.userBal=(el)=>balanceModal(itm(el).uid,itm(el).username,itm(el).balance);
ACT.userReset=async(el)=>{const u=itm(el);const r=await api('POST',`/api/admin/users/${encodeURIComponent(u.uid)}/reset-link`);modal(`<p class="muted fs13">Send this one-time link to <b>${esc(u.username)}</b> (valid ${r.expiresInMin} minutes). Passwords are hashed, so they can never be viewed — only reset.</p><div class="keybox"><span>${esc(r.link)}</span><button class="btn icon sm" data-copy="${esc(r.link)}">${ico('copy','sm')}</button></div>`,{title:'Password reset link'})};
ACT.userDel=async(el)=>{const u=itm(el);if(await confirmDlg('Delete user',`Permanently delete <b>${esc(u.username)}</b>? Orders and ledger entries stay for accounting.`,{danger:true,ok:'Delete'})){await api('DELETE','/api/admin/users/'+encodeURIComponent(u.uid));done('Deleted');A.lpPaint()}};
function balanceModal(uid,name,bal){const m=modal(`<div class="alert info" style="margin-bottom:12px">${ico('wallet')}<div>${esc(name)} — current balance <b>${money(bal)}</b></div></div><div class="seg" style="margin-bottom:12px"><button class="on" data-mode="add">Add balance</button><button data-mode="deduct">Deduct balance</button></div><div class="fgrid">${fld('amount','Amount (₹)','',{type:'number',step:'0.01',min:0.01,req:true})}${fld('note','Note (shown in ledger)','',{ph:'optional'})}</div>`,{title:'Add / Deduct balance',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Apply</button>'});let mode='add';
  m.ov.addEventListener('click',async e=>{const s=e.target.closest('[data-mode]');if(s){mode=s.dataset.mode;$$('[data-mode]',m.el).forEach(x=>x.classList.toggle('on',x===s));return}const b=e.target.closest('[data-sv]');if(!b)return;const f=readF(m.el);if(!(parseFloat(f.amount)>0))return toast('Enter an amount','err');
    if(!await confirmDlg(mode==='add'?'Add balance':'Deduct balance',`${mode==='add'?'Add':'Deduct'} <b>${money(f.amount)}</b> ${mode==='add'?'to':'from'} ${esc(name)}?`))return;
    await withBusy(b,async()=>{try{const r=await api('POST',`/api/admin/users/${encodeURIComponent(uid)}/balance`,{action:mode,amount:parseFloat(f.amount),note:f.note});m.close();done('New balance '+money(r.balance));if(A.lpPaint&&$('#lp_body'))A.lpPaint()}catch(er){toast(er.message,'err')}})})}

/* ================= Orders / Transactions / Wallets ================= */
V.orders=(c)=>listPage(c,'orders',{title:'Orders',path:'/api/admin/orders',ph:'Search order id, user, product, PID, key…',filters:[{k:'status',label:'All status',opts:['delivered','partial','failed','refunded','needs_review','processing','pending']},{k:'source',label:'All sources',opts:['web','api']}],
  summary:(r)=>`<div>Orders<b>${r.summary.count}</b></div><div>Revenue<b>${money(r.summary.revenue)}</b></div><div>Supplier cost<b>${money(r.summary.cost)}</b></div>`,cols:['Order','User','NAME','PID','Duration','Qty','Total','Delivery','Status','Date',''],
  row:(o,i)=>[mini(o.id),esc(o.username),`<b>${esc(o.productName)}</b>`,`<span class="pid">${esc(o.pid)}</span>`,esc(o.duration),o.deliveredQty??o.qty,money(o.total),`<span class="badge">${esc((o.source||'web').toUpperCase())}</span> ${o.supplierId?'<span class="badge vio">SUPPLIER</span>':'<span class="badge">STOCK</span>'}`,statusBadge(o.status)+(o.failReason?`<div class="muted fs12">${esc(o.failReason)}</div>`:''),`<span class="muted fs12">${dtxt(o.createdAt)}</span>`,rowBtns('orders',i,[['orderView','','eye'],...(['delivered','partial','needs_review','processing'].includes(o.status)&&can('wallet')?[['orderRefund','','refresh','danger']]:[]),...(['needs_review','processing'].includes(o.status)?[['orderDeliver','Deliver','key','ok']]:[])])]});
ACT.orderView=(el)=>{const o=itm(el);modal(['id','username','productName','pid','duration','qty','unitPrice','total','refunded','status','source','supplierId','cost','profit','failReason','createdAt'].filter(k=>o[k]!==undefined&&o[k]!=='').map(k=>`<div class="field-lbl-row" style="display:grid;grid-template-columns:130px 1fr;gap:10px;padding:8px 0;border-bottom:1px solid var(--border)"><b class="acc fs12 up">${k}</b><span style="word-break:break-all">${esc(k.endsWith('At')?dtxt(o[k]):o[k])}</span></div>`).join('')+((o.keys||[]).length?`<h4 style="margin:14px 0 8px">Keys</h4>${o.keys.map(k=>`<div class="keybox"><span>${esc(k)}</span><button class="btn icon sm" data-copy="${esc(k)}">${ico('copy','sm')}</button></div>`).join('')}`:''),{title:'Order '+esc(o.id),size:'lg'})};
ACT.orderRefund=async(el)=>{const o=itm(el);if(await confirmDlg('Refund order',`Refund <b>${money(o.total-(o.refunded||0))}</b> to ${esc(o.username)}? This is recorded in the ledger.`,{danger:true,ok:'Refund'})){try{await api('POST',`/api/admin/orders/${encodeURIComponent(o.id)}/refund`,{reason:'Admin refund'});done('Refunded');A.lpPaint()}catch(er){toast(er.message,'err')}}};
ACT.orderDeliver=(el)=>{const o=itm(el);const m=modal(`<p class="muted fs13">Paste the keys to deliver for order <b>${esc(o.id)}</b> (one per line).</p>${fld('keys','Keys','',{type:'textarea',rows:5})}`,{title:'Manual delivery',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Deliver</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{await api('POST',`/api/admin/orders/${encodeURIComponent(o.id)}/deliver`,{keys:readF(m.el).keys});m.close();done('Delivered');A.lpPaint()}catch(er){toast(er.message,'err')}})})};
V.transactions=(c)=>listPage(c,'tx',{title:'Transactions',path:'/api/admin/transactions',ph:'Search user, description, order id…',filters:[{k:'dir',label:'In & out',opts:['in','out']},{k:'type',label:'All types',opts:['Deposit','Generation','Refund','Commission','AdminDebit']}],summary:(r)=>`<div>Entries<b>${r.summary.count}</b></div><div>Money in<b class="ok">${money(r.summary.in)}</b></div><div>Money out<b class="err">${money(r.summary.out)}</b></div>`,cols:['Date','User','Type','Direction','Amount','Description'],
  row:(t)=>[`<span class="muted fs12">${dtxt(t.ts)}</span>`,esc(t.username||t.uid),statusBadge(t.type),t.direction==='in'?'<span class="badge ok">IN</span>':'<span class="badge err">OUT</span>',`<b class="${t.direction==='in'?'ok':'err'}">${money(t.amount)}</b>`,`<span class="muted">${esc(t.description||'')}</span>`]});
const walletList=(c,k,title,sub,withActions)=>listPage(c,k,{title,sub,path:'/api/admin/wallets',ph:'Search username or UID…',summary:(r)=>`<div>Users<b>${r.total}</b></div><div>Total in wallets<b>${money(r.total_balance)}</b></div>`,cols:['User','UID','Role','Balance','Status',...(withActions?['']:[])],
  row:(u,i)=>[`<b>${esc(u.username)}</b>`,mini(u.uid),statusBadge(u.role),`<b>${money(u.balance)}</b>`,u.banned?statusBadge('BANNED'):statusBadge('ACTIVE'),...(withActions?[rowBtns(k,i,[['walAdd','Add','plus','ok'],['walDed','Deduct','minus','danger']])]:[])]});
V.wallets=(c)=>walletList(c,'wallets','Wallet Management','Every user wallet, highest first',false);
V.balance=(c)=>walletList(c,'balance','Add / Deduct Balance','Search a user, then add or deduct — every change is written to the ledger and audit log',true);
ACT.walAdd=ACT.walDed=(el)=>{const u=itm(el);balanceModal(u.uid,u.username,u.balance)};
V.tickets=async(c)=>{const r=await api('GET','/api/admin/tickets');A.items.tk=r.items;c.innerHTML=`<div class="view">${head('Support Tickets',`${r.items.length} tickets`)}${r.items.length?r.items.map((t,i)=>`<div class="card" style="margin-bottom:12px"><div class="row wrap"><b>${esc(t.subject)}</b>${statusBadge(t.status)}<span class="muted fs12">@${esc(t.username)} • ${dtxt(t.createdAt)}</span><div class="sp"></div>${abtn('tkReply',t.reply?'Edit reply':'Reply','send','',{k:'tk',i})}</div><div class="muted" style="margin-top:8px;white-space:pre-wrap">${esc(t.message)}</div>${t.reply?`<div class="alert ok" style="margin-top:10px">${ico('mail')}<div><b>Reply</b><br>${esc(t.reply)}</div></div>`:''}</div>`).join(''):`<div class="card">${emptyBox('lifebuoy','No tickets')}</div>`}</div>`};
ACT.tkReply=(el)=>{const t=itm(el);const m=modal(fld('reply','Reply',t.reply||'',{type:'textarea',rows:5}),{title:'Reply to '+esc(t.username),footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Send</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{await api('POST',`/api/admin/tickets/${encodeURIComponent(t.id)}/reply`,{reply:readF(m.el).reply});m.close();done('Reply sent');reload()}catch(er){toast(er.message,'err')}})})};

/* ================= Products ================= */
const planLine=(p,pl)=>`<div class="pl"><b>${esc(String(pl.duration).toUpperCase())}</b><span>U: <b class="ok">${money(pl.price)}</b></span><span>R: <b class="ok">${money(pl.rprice??pl.price)}</b></span><span class="muted">${pl.cost==null?'—':'Cost '+money(pl.cost)}</span><span class="${pl.profitUser>0?'ok':pl.profitUser<0?'err':'muted'}">${pl.profitUser==null?'—':'+'+money(pl.profitUser)}</span></div>`;
V.products=async(c)=>{const r=await api('GET','/api/admin/products');A.items.prod=r.products;A.nextPid=r.nextPid;const st=A.lp.prod||(A.lp.prod={q:'',cat:'',stat:''});const cats=[...new Set(r.products.map(p=>String(p.category||'').toUpperCase()).filter(Boolean))];
  const paint=()=>{const q=st.q.toLowerCase();const l=r.products.map((p,i)=>[p,i]).filter(([p])=>(!q||[p.name,p.pid,p.category].join(' ').toLowerCase().includes(q))&&(!st.cat||String(p.category).toUpperCase()===st.cat)&&(!st.stat||p.displayStatus===st.stat));
    $('#pgrid').innerHTML=l.length?l.map(([p,i])=>`<div class="card pcard hover"><div class="top"><div class="nm trunc">${esc(p.name)}</div><span class="pid">${esc(p.pid)}</span></div><div class="row wrap gap6">${statusBadge(p.displayStatus)}<span class="badge info">${esc(String(p.category||'GENERAL').toUpperCase())}</span>${p.badge?`<span class="badge warn">${esc(p.badge)}</span>`:''}</div><div><div class="pl h"><span>Duration</span><span>User</span><span>Reseller</span><span>Cost</span><span>Profit</span></div>${p.plans.map(pl=>planLine(p,pl)).join('')}<div class="hint" style="margin-top:6px">Stock: ${p.plans.map(pl=>`${esc(pl.duration)} <b>${pl.stock}</b>${pl.mappings.length?' +API':''}`).join(' • ')}</div></div><div class="row wrap gap6">${abtn('prodEdit','Edit','edit','',{k:'prod',i})}${abtn('prodToggle',p.status==='INACTIVE'?'Activate':'Deactivate',p.status==='INACTIVE'?'check':'ban',p.status==='INACTIVE'?'ok':'',{k:'prod',i})}${abtn('prodDel','','trash','danger',{k:'prod',i})}</div></div>`).join(''):`<div class="card" style="grid-column:1/-1">${emptyBox('package','No products match')}</div>`};
  c.innerHTML=`<div class="view">${head('Products','Each product has NAME, PID ID, PRICE, DURATION, STATUS, CATEGORY and DESCRIPTION',`<button class="btn primary" data-act="prodNew">${ico('plus','sm')} Add product</button>`)}<div class="fbar"><div class="input-wrap grow">${ico('search')}<input class="input" id="pq" placeholder="Search name, PID, category…" value="${esc(st.q)}"></div><select class="input" id="pc"><option value="">All categories</option>${cats.map(x=>`<option ${st.cat===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select class="input" id="ps"><option value="">All status</option><option ${st.stat==='ACTIVE'?'selected':''}>ACTIVE</option><option ${st.stat==='INACTIVE'?'selected':''}>INACTIVE</option><option ${st.stat==='MAINTENANCE'?'selected':''}>MAINTENANCE</option></select></div><div class="pgrid" id="pgrid"></div></div>`;paint();
  $('#pq').addEventListener('input',debounce(e=>{st.q=e.target.value;paint()},150));$('#pc').addEventListener('change',e=>{st.cat=e.target.value;paint()});$('#ps').addEventListener('change',e=>{st.stat=e.target.value;paint()})};
const planRow=(p={})=>`<div class="planrow" data-plan data-pk="${esc(p.pk||'')}"><input class="input" data-pf="duration" placeholder="DURATION e.g. 1 Day" value="${esc(p.duration||'')}"><input class="input" data-pf="price" type="number" step="0.01" min="0" placeholder="User ₹" value="${p.price??''}"><input class="input" data-pf="rprice" type="number" step="0.01" min="0" placeholder="Reseller ₹" value="${p.rprice??''}"><button type="button" class="btn icon sm danger" data-act="planDel" aria-label="Remove">${ico('trash','sm')}</button></div>`;
const mediaField=(id,label,val,kind)=>`<div class="field" style="grid-column:1/-1"><label>${label}</label><div class="row"><input class="input" data-f="${id}" id="f_${id}" value="${esc(val||'')}" placeholder="https://… or /media/…"><button type="button" class="btn sm" data-act="pickMedia" data-t="f_${id}" data-kind="${kind}">${ico('image','sm')} Library</button></div></div>`;
function productModal(p){const isNew=!p;p=p||{plans:[{duration:'1 Day',price:'',rprice:''}],status:'ACTIVE'};
  const m=modal(`<div class="fgrid">${fld('name','NAME',p.name||'',{req:true,span:true})}${fld('pid','PID ID',p.pid||'',{ph:isNew?'Auto: '+A.nextPid:'',hint:isNew?'Leave empty to auto-assign the next free PID. Must be unique.':'Unique ID. Changing it keeps orders & mappings.'})}${fld('category','CATEGORY',p.category||'',{ph:'e.g. ANDROID, FREE FIRE'})}${fld('status','STATUS',p.status||'ACTIVE',{type:'select',opts:['ACTIVE','INACTIVE']})}${fld('badge','Badge',p.badge||'',{type:'select',opts:[['','None'],'NEW','HOT','BEST SELLER']})}${fld('game','Game / tag',p.game||'')}${fld('tags','Tags (comma separated)',(p.tags||[]).join(', '))}${fld('description','DESCRIPTION',p.description||'',{type:'textarea',span:true,rows:3})}${fld('features','Features (one per line)',(p.features||[]).join('\n'),{type:'textarea',span:true,rows:3})}${mediaField('imageUrl','Product image',p.imageUrl,'image')}${mediaField('thumbnailUrl','Thumbnail',p.thumbnailUrl,'image')}${mediaField('bannerUrl','Banner',p.bannerUrl,'image')}${mediaField('videoUrl','Product video (YouTube/mp4 URL)',p.videoUrl,'video')}${fld('downloadUrl','Download URL',p.downloadUrl||'',{span:true})}</div><h4 style="margin:18px 0 4px">DURATION &amp; PRICE</h4><div class="hint" style="margin-bottom:8px">Add as many durations as you need. Each has its own user and reseller price.</div><div id="plans">${(p.plans||[]).map(planRow).join('')}</div><button type="button" class="btn sm" data-act="planAdd">${ico('plus','sm')} Add duration</button>`,{title:isNew?'Add product':'Edit '+esc(p.name),size:'lg',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Save product</button>'});
  m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;const f=readF(m.el);const plans=$$('[data-plan]',m.el).map(r=>({pk:r.dataset.pk,duration:$('[data-pf=duration]',r).value,price:$('[data-pf=price]',r).value,rprice:$('[data-pf=rprice]',r).value}));
    const body={...f,tags:f.tags.split(',').map(s=>s.trim()).filter(Boolean),features:f.features,plans};await withBusy(b,async()=>{try{const r=await api(isNew?'POST':'PUT',isNew?'/api/admin/products':'/api/admin/products/'+encodeURIComponent(p.key),body);m.close();done(`Saved — PID ${r.pid}`);reload()}catch(er){toast(er.message,'err',6000)}})});}
ACT.prodNew=()=>productModal(null);ACT.prodEdit=(el)=>productModal(itm(el));
ACT.planAdd=(el)=>{const m=el.closest('.modal');$('#plans',m).insertAdjacentHTML('beforeend',planRow())};ACT.planDel=(el)=>{const m=el.closest('.modal');if($$('[data-plan]',m).length>1)el.closest('[data-plan]').remove();else toast('At least one duration is required','err')};
ACT.prodToggle=async(el)=>{const p=itm(el);await api('PATCH',`/api/admin/products/${encodeURIComponent(p.key)}/status`,{status:p.status==='INACTIVE'?'ACTIVE':'INACTIVE'});done('Status updated');reload()};
ACT.prodDel=async(el)=>{const p=itm(el);if(await confirmDlg('Delete product',`Delete <b>${esc(p.name)}</b> (PID ${esc(p.pid)}) with all durations, stock and supplier mappings? This cannot be undone.`,{danger:true,ok:'Delete'})){await api('DELETE','/api/admin/products/'+encodeURIComponent(p.key));done('Deleted');reload()}};

/* ================= PID management & supplier mappings ================= */
V.pids=async(c)=>{const [pr,mp,su]=await Promise.all([api('GET','/api/admin/products'),can('suppliers')?api('GET','/api/admin/mappings'):{mappings:[]},can('suppliers')?api('GET','/api/admin/suppliers'):{suppliers:[]}]);A.items.pid=pr.products;A.items.map=mp.mappings;A.sups=su.suppliers;A.prods=pr.products;
  c.innerHTML=`<div class="view">${head('PID Management','ARYAN PID IDs are yours. Supplier PIDs are mapped to them separately — they never have to match',`<button class="btn" data-act="pidAssign">${ico('hash','sm')} Assign missing PIDs</button>`)}
  <div class="card" style="margin-bottom:16px"><div class="card-h">${ico('hash')}<h3>ARYAN PID IDs</h3></div>${table(['NAME','PID ID','CATEGORY','STATUS','Durations',''],pr.products.map((p,i)=>[`<b>${esc(p.name)}</b>`,`<span class="pid">${esc(p.pid)}</span>`,esc(p.category),statusBadge(p.displayStatus),p.plans.map(x=>esc(x.duration)).join(', '),rowBtns('pid',i,[['pidEdit','Change PID','edit']])]))}</div>
  ${can('suppliers')?`<div class="card"><div class="card-h">${ico('link')}<h3>Supplier PID mapping</h3><div class="sp"></div><button class="btn primary sm" data-act="mapNew">${ico('plus','sm')} Add mapping</button></div><div class="hint" style="margin-bottom:10px">Example: Supplier PID <b>9876</b> → ARYAN PID <b>151</b>, cost ₹10, selling ₹15, profit ₹5. Customers only ever see the ARYAN PID.</div>${table(['Supplier','Supplier PID','Supplier duration','→ ARYAN PID','Product','Duration','Cost','Sell (U)','Profit','Priority','Status',''],mp.mappings.map((m,i)=>[esc(m.supplier),`<span class="pid">${esc(m.supplierPid)}</span>`,esc(m.supplierDuration),`<span class="pid">${esc(m.aryanPid)}</span>`,esc(m.productName),esc(m.duration),money(m.cost),m.sellPrice==null?'—':money(m.sellPrice),m.profit==null?'—':`<b class="${m.profit>=0?'ok':'err'}">${money(m.profit)}</b>`,m.priority,m.enabled!==false?statusBadge('ACTIVE'):statusBadge('INACTIVE'),rowBtns('map',i,[['mapEdit','','edit'],['mapDel','','trash','danger']])]),{empty:'No mappings yet'})}</div>`:''}</div>`};
ACT.pidAssign=async()=>{const r=await api('POST','/api/admin/pids/assign-missing');done(`${r.assigned} PID(s) assigned`);reload()};
ACT.pidEdit=(el)=>{const p=itm(el);const m=modal(fld('pid','PID ID',p.pid,{hint:'Letters, numbers, - and _ (max 20). Must be unique.'}),{title:`PID for ${esc(p.name)}`,footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Save</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{await api('PUT',`/api/admin/products/${encodeURIComponent(p.key)}/pid`,{pid:readF(m.el).pid});m.close();done();reload()}catch(er){toast(er.message,'err')}})})};
function mapModal(mp){const isNew=!mp;mp=mp||{enabled:true,priority:100,cost:''};if(!A.sups.length)return toast('Add a supplier first (Supplier Panels)','err');
  const prodOpts=A.prods.map(p=>[p.key,`${p.name} (PID ${p.pid})`]);const m=modal(`<div class="fgrid">${fld('supplierId','Supplier',mp.supplierId||A.sups[0].id,{type:'select',opts:A.sups.map(s=>[s.id,s.name])})}${fld('supplierPid','Supplier PID',mp.supplierPid||'',{req:true,hint:'The product ID on the supplier panel'})}${fld('productKey','ARYAN product',mp.productKey||A.prods[0].key,{type:'select',opts:prodOpts})}<div class="field"><label>ARYAN duration</label><select class="input" data-f="planKey" id="f_planKey"></select></div>${fld('supplierDuration','Supplier duration value',mp.supplierDuration||'',{hint:'Sent to supplier. Empty = same as ARYAN duration'})}${fld('cost','Supplier cost (₹)',mp.cost,{type:'number',step:'0.01',min:0,req:true})}${fld('priority','Priority (1 = first)',mp.priority,{type:'number',min:1})}${fld('enabled','Enabled',mp.enabled!==false,{type:'check'})}${fld('note','Note',mp.note||'',{span:true})}</div><div id="mpProfit" class="alert info" style="margin-top:12px"></div>`,{title:isNew?'Add supplier mapping':'Edit mapping',size:'lg',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Save mapping</button>'});
  const sync=()=>{const p=A.prods.find(x=>x.key===$('#f_productKey',m.el).value);const ps=$('#f_planKey',m.el);const cur=ps.value||mp.planKey;ps.innerHTML=p.plans.map(pl=>`<option value="${esc(pl.pk)}" ${pl.pk===cur?'selected':''}>${esc(pl.duration)} — ${money(pl.price)}</option>`).join('');calc()};
  const calc=()=>{const p=A.prods.find(x=>x.key===$('#f_productKey',m.el).value);const pl=p.plans.find(x=>x.pk===$('#f_planKey',m.el).value);const cost=parseFloat($('#f_cost',m.el).value)||0;if(!pl)return;$('#mpProfit',m.el).innerHTML=`${ico('dollar')}<div>ARYAN PID <b>${esc(p.pid)}</b> • User price <b>${money(pl.price)}</b> → profit <b class="${pl.price-cost>=0?'ok':'err'}">${money(pl.price-cost)}</b> • Reseller price <b>${money(pl.rprice??pl.price)}</b> → profit <b>${money((pl.rprice??pl.price)-cost)}</b></div>`};
  $('#f_productKey',m.el).addEventListener('change',()=>{$('#f_planKey',m.el).value='';sync()});$('#f_planKey',m.el).addEventListener('change',calc);$('#f_cost',m.el).addEventListener('input',calc);sync();
  m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{await api(isNew?'POST':'PUT',isNew?'/api/admin/mappings':'/api/admin/mappings/'+encodeURIComponent(mp.id),readF(m.el));m.close();done('Mapping saved');reload()}catch(er){toast(er.message,'err',6000)}})})}
ACT.mapNew=()=>mapModal(null);ACT.mapEdit=(el)=>mapModal(itm(el));
ACT.mapDel=async(el)=>{const m=itm(el);if(await confirmDlg('Delete mapping',`Remove supplier PID ${esc(m.supplierPid)} → ARYAN PID ${esc(m.aryanPid)}?`,{danger:true})){await api('DELETE','/api/admin/mappings/'+encodeURIComponent(m.id));done('Removed');reload()}};

/* ================= Prices / Durations ================= */
V.prices=async(c)=>{const r=await api('GET','/api/admin/products');const rows=[];r.products.forEach(p=>p.plans.forEach(pl=>rows.push({p,pl})));
  c.innerHTML=`<div class="view">${head('Price Mgmt','Edit user and reseller price for any duration, then save all changes at once',`<button class="btn primary" data-act="priceSave">${ico('check','sm')} Save changes</button>`)}<div class="fbar"><div class="input-wrap grow">${ico('search')}<input class="input" id="prq" placeholder="Filter by name or PID…"></div></div><div class="tbl-wrap"><table class="tbl rsp"><thead><tr><th>NAME</th><th>PID ID</th><th>DURATION</th><th>User price ₹</th><th>Reseller price ₹</th><th>Cost</th><th>Profit (U)</th></tr></thead><tbody id="prbody">${rows.map((x,i)=>`<tr data-s="${esc((x.p.name+' '+x.p.pid).toLowerCase())}"><td data-l="NAME"><b>${esc(x.p.name)}</b></td><td data-l="PID ID"><span class="pid">${esc(x.p.pid)}</span></td><td data-l="DURATION">${esc(x.pl.duration)}</td><td data-l="User price"><input class="input" style="width:110px;min-height:34px" type="number" step="0.01" min="0" data-pk="${esc(x.p.key)}" data-pl="${esc(x.pl.pk)}" data-o="${x.pl.price}" data-w="price" value="${x.pl.price}"></td><td data-l="Reseller price"><input class="input" style="width:110px;min-height:34px" type="number" step="0.01" min="0" data-pk="${esc(x.p.key)}" data-pl="${esc(x.pl.pk)}" data-o="${x.pl.rprice??x.pl.price}" data-w="rprice" value="${x.pl.rprice??x.pl.price}"></td><td data-l="Cost">${x.pl.cost==null?'—':money(x.pl.cost)}</td><td data-l="Profit">${x.pl.profitUser==null?'—':money(x.pl.profitUser)}</td></tr>`).join('')}</tbody></table></div></div>`;
  $('#prq').addEventListener('input',e=>{const q=e.target.value.toLowerCase();$$('#prbody tr').forEach(t=>t.style.display=t.dataset.s.includes(q)?'':'none')})};
ACT.priceSave=async(el)=>{const map={};$$('#prbody input').forEach(i=>{const k=i.dataset.pk+'|'+i.dataset.pl;(map[k]||(map[k]={key:i.dataset.pk,pk:i.dataset.pl}))[i.dataset.w]=i.value;if(i.value!==i.dataset.o)map[k].changed=true});const rows=Object.values(map).filter(r=>r.changed).map(({changed,...r})=>r);if(!rows.length)return toast('No changes to save','info');await withBusy(el,async()=>{try{const r=await api('POST','/api/admin/prices',{rows});done(`${r.updated} price row(s) updated`);reload()}catch(er){toast(er.message,'err',6000)}})};
V.durations=async(c)=>{const r=await api('GET','/api/admin/durations');A.items.dur=r.durations;c.innerHTML=`<div class="view">${head('Duration Mgmt','Rename a duration label everywhere (e.g. “1 Day” → “1 DAY”) or inspect where it is used')}${table(['Duration','Used in','Products',''],r.durations.map((d,i)=>[`<b>${esc(d.label)}</b>${d.variants.length>1?`<div class="muted fs12">Variants: ${d.variants.map(esc).join(', ')}</div>`:''}`,d.count+' plan(s)',d.products.slice(0,6).map(p=>`${esc(p.name)} <span class="pid">${esc(p.pid)}</span>`).join(' • ')+(d.products.length>6?' …':''),rowBtns('dur',i,[['durRename','Rename','edit']])]),{empty:'No durations yet'})}</div>`};
ACT.durRename=(el)=>{const d=itm(el);const m=modal(fld('to','New label',d.label,{hint:`Applies to all ${d.count} plan(s). Products that already have the new label are skipped.`}),{title:'Rename “'+esc(d.label)+'”',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Rename</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{const r=await api('POST','/api/admin/durations/rename',{from:d.label,to:readF(m.el).to});m.close();done(`${r.renamed} renamed`+(r.skippedBecauseDuplicate.length?`, ${r.skippedBecauseDuplicate.length} skipped (duplicate)`:''));reload()}catch(er){toast(er.message,'err')}})})};

/* ================= Key stock / videos ================= */
V.stock=async(c)=>{const r=await api('GET','/api/admin/stock');A.items.stock=r.rows;c.innerHTML=`<div class="view">${head('Key Stock',`${r.total} keys in stock across ${r.rows.length} durations`)}${table(['NAME','PID ID','DURATION','In stock','Supplier maps',''],r.rows.map((x,i)=>[`<b>${esc(x.name)}</b>`,`<span class="pid">${esc(x.pid)}</span>`,esc(x.duration),`<b class="${x.stock?'ok':'err'}">${x.stock}</b>`,x.suppliers||'—',rowBtns('stock',i,[['stAdd','Add keys','plus','primary'],['stView','','eye'],['stClear','','trash','danger']])]))}</div>`};
ACT.stAdd=(el)=>{const x=itm(el);const m=modal(`<p class="muted fs13">${esc(x.name)} • PID ${esc(x.pid)} • ${esc(x.duration)}</p>${fld('keys','Keys (one per line, duplicates are skipped)','',{type:'textarea',rows:8})}`,{title:'Add keys',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Add</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{const r=await api('POST','/api/admin/stock',{productKey:x.key,planKey:x.pk,keys:readF(m.el).keys});m.close();done(`${r.added} added, ${r.duplicates} duplicate(s) skipped`);reload()}catch(er){toast(er.message,'err')}})})};
ACT.stView=async(el)=>{const x=itm(el);const r=await api('GET',`/api/admin/stock/${encodeURIComponent(x.key)}/${encodeURIComponent(x.pk)}`);const m=modal(`<div class="hint" style="margin-bottom:8px">Keys are masked. ${r.total} total (showing first 200).</div>${r.keys.map(k=>`<div class="row" style="padding:6px 0;border-bottom:1px solid var(--border)"><span class="mono sp">${esc(k.masked)}</span><button class="btn icon sm danger" data-rm="${esc(k.id)}">${ico('trash','sm')}</button></div>`).join('')||emptyBox('key','Empty')}`,{title:'Stock — '+esc(x.name)+' '+esc(x.duration)});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-rm]');if(!b)return;await api('DELETE',`/api/admin/stock/${encodeURIComponent(x.key)}/${encodeURIComponent(x.pk)}/${encodeURIComponent(b.dataset.rm)}`);b.closest('.row').remove();toast('Removed','ok',1500)})};
ACT.stClear=async(el)=>{const x=itm(el);if(await confirmDlg('Clear stock',`Delete all ${x.stock} keys for ${esc(x.name)} ${esc(x.duration)}?`,{danger:true,ok:'Clear'})){await api('DELETE',`/api/admin/stock/${encodeURIComponent(x.key)}/${encodeURIComponent(x.pk)}`);done('Cleared');reload()}};
V.videos=async(c)=>{const r=await api('GET','/api/admin/products');A.items.vid=r.products;c.innerHTML=`<div class="view">${head('Product Videos','Attach a demo video (YouTube link, MP4 URL or uploaded file) to each product')}${table(['NAME','PID ID','Video',''],r.products.map((p,i)=>[`<b>${esc(p.name)}</b>`,`<span class="pid">${esc(p.pid)}</span>`,p.videoUrl?`<a href="${esc(safeUrl(p.videoUrl)||'#')}" target="_blank" rel="noopener" class="trunc" style="display:inline-block;max-width:340px">${esc(p.videoUrl)}</a>`:'<span class="muted">No video</span>',rowBtns('vid',i,[['vidSet','Set video','video'],...(p.videoUrl?[['vidClear','','trash','danger']]:[])])]))}</div>`};
ACT.vidSet=(el)=>{const p=itm(el);const m=modal(mediaField('url','Video URL',p.videoUrl,'video')+'<div class="hint">http(s) link or choose/upload in the Media Library.</div>',{title:'Video — '+esc(p.name),footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Save</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{await api('POST','/api/admin/media/assign',{target:'productVideo',productKey:p.key,url:readF(m.el).url});m.close();done();reload()}catch(er){toast(er.message,'err')}})})};
ACT.vidClear=async(el)=>{const p=itm(el);await api('POST','/api/admin/media/assign',{target:'productVideo',productKey:p.key,url:''});done('Removed');reload()};

/* ================= Suppliers ================= */
const stTxt=(s)=>({ok:'CONNECTED',error:'ERROR',unknown:'NOT_TESTED',reachable:'REACHABLE',not_configured:'NOT_CONFIGURED'}[s]||String(s||'NOT_TESTED').toUpperCase());
V.suppliers=async(c)=>{const r=await api('GET','/api/admin/suppliers');A.items.sup=r.suppliers;A.supPresets=r.presets;
  c.innerHTML=`<div class="view">${head('Supplier Panels','Secrets are encrypted at rest and never shown. Balance / test run only when an endpoint is configured.',`<button class="btn" data-act="supLogs">${ico('activity','sm')} Logs</button><button class="btn primary" data-act="supNew">${ico('plus','sm')} Add supplier</button>`)}${r.suppliers.length?`<div class="pgrid">${r.suppliers.map((s,i)=>`<div class="card pcard"><div class="top"><div class="nm trunc">${esc(s.name)}</div>${statusBadge(s.enabled?stTxt(s.status):'INACTIVE')}</div><dl class="kv"><dt>Preset</dt><dd>${esc(s.preset)}</dd><dt>API URL</dt><dd class="mono fs12">${esc(s.apiUrl||'—')}</dd><dt>API key</dt><dd class="mono">${esc(s.apiKeyMask||'not set')}</dd><dt>Master key</dt><dd class="mono">${esc(s.masterKeyMask||'—')}</dd><dt>Priority</dt><dd>${s.priority}</dd><dt>Orders</dt><dd><span class="ok">${s.stats.ok} ok</span> • <span class="err">${s.stats.failed} failed</span></dd><dt>Balance</dt><dd>${s.lastBalance==null?'<span class="muted">unknown</span>':money(s.lastBalance)}</dd></dl>${s.statusNote?`<div class="hint">${esc(s.statusNote)}</div>`:''}<div class="row wrap gap6">${abtn('supEdit','Edit','edit','',{k:'sup',i})}${abtn('supTest','Test','zap','',{k:'sup',i})}${abtn('supBal','Balance','dollar','',{k:'sup',i})}${abtn('supReveal','','eye','',{k:'sup',i})}${abtn('supDel','','trash','danger',{k:'sup',i})}</div></div>`).join('')}</div>`:`<div class="card">${emptyBox('server','No suppliers yet. Add your supplier panel to enable automatic delivery.')}</div>`}</div>`};
function supModal(s){const isNew=!s;const P=A.supPresets;s=s||{preset:'reseller_v1',enabled:true,priority:100,fields:P.reseller_v1.fields,apiUrl:P.reseller_v1.apiUrl,bodyFormat:'form',authMode:'body',masterHeader:'x-master-key',buyAction:'buy',keysPath:'keys',singleKeyPath:'key',errorPath:'message'};const f=s.fields||{};
  const m=modal(`<div class="fgrid">${fld('name','Supplier name',s.name||'',{req:true})}${fld('preset','Preset',s.preset,{type:'select',opts:Object.entries(P).map(([k,v])=>[k,v.label])})}${fld('apiUrl','API URL',s.apiUrl||'',{span:true})}${fld('apiKey','API key',"",{type:'password',ph:s.apiKeyMask?'Saved — leave empty to keep':'',hint:'Stored encrypted on the server'})}${fld('masterKey','Master key (if the provider uses one)','',{type:'password',ph:s.masterKeyMask?'Saved — leave empty to keep':''})}${fld('password','Panel password (optional)','',{type:'password',ph:s.passwordMask?'Saved — leave empty to keep':''})}${fld('username','Panel username (optional)',s.username||'')}${fld('priority','Priority (1 = first)',s.priority,{type:'number',min:1})}${fld('enabled','Enabled',s.enabled!==false,{type:'check'})}</div>
  <details style="margin-top:14px"><summary class="fw6" style="cursor:pointer;color:var(--accent)">Request format (from the provider’s documentation)</summary><div class="fgrid" style="margin-top:12px">${fld('bodyFormat','Body format',s.bodyFormat||'form',{type:'select',opts:['form','json']})}${fld('authMode','Auth mode',s.authMode||'body',{type:'select',opts:['body','bearer','basic']})}${fld('masterHeader','Master key header',s.masterHeader||'')}${fld('buyAction','Buy action value',s.buyAction||'buy')}${fld('f_apiKey','Field: api key',f.apiKey||'api_key')}${fld('f_action','Field: action',f.action||'action')}${fld('f_pid','Field: product id',f.pid||'product_id')}${fld('f_duration','Field: duration',f.duration||'duration')}${fld('f_qty','Field: quantity',f.qty||'quantity')}${fld('keysPath','Response path: keys[]',s.keysPath||'keys')}${fld('singleKeyPath','Response path: single key',s.singleKeyPath||'key')}${fld('errorPath','Response path: error message',s.errorPath||'message')}${fld('balanceUrl','Balance URL (optional)',s.balanceUrl||'',{span:true,hint:'Balance check is shown only when this or a balance action is set'})}${fld('balanceAction','Balance action (optional)',s.balanceAction||'')}${fld('balancePath','Balance response path',s.balancePath||'')}${fld('extraFields','Extra fields (JSON)',typeof s.extraFields==='object'?(Object.keys(s.extraFields||{}).length?fmtJ(s.extraFields):''):s.extraFields||'',{type:'textarea',span:true,rows:2,ph:'{"android_id":"abc"}'})}</div></details><div class="alert warn" style="margin-top:14px">${ico('info')}<div>Only the fields your provider documents are used. If unsure, ask the supplier for their API documentation — nothing is guessed.</div></div>`,{title:isNew?'Add supplier':'Edit '+esc(s.name),size:'lg',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Save supplier</button>'});
  $('#f_preset',m.el).addEventListener('change',e=>{const p=P[e.target.value];if(!p)return;$('#f_apiUrl',m.el).value=p.apiUrl||'';$('#f_bodyFormat',m.el).value=p.bodyFormat;$('#f_authMode',m.el).value=p.authMode;$('#f_masterHeader',m.el).value=p.masterHeader||'';$('#f_buyAction',m.el).value=p.buyAction||'buy';const q=p.fields||{};['apiKey','action','pid','duration','qty'].forEach(k=>$('#f_f_'+k,m.el).value=q[k]||'')});
  m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;const v=readF(m.el);const body={...v,fields:{apiKey:v.f_apiKey,action:v.f_action,pid:v.f_pid,duration:v.f_duration,qty:v.f_qty}};['apiKey','masterKey','password'].forEach(k=>{if(!body[k])delete body[k]});await withBusy(b,async()=>{try{await api(isNew?'POST':'PUT',isNew?'/api/admin/suppliers':'/api/admin/suppliers/'+encodeURIComponent(s.id),body);m.close();done('Supplier saved');reload()}catch(er){toast(er.message,'err',7000)}})})}
ACT.supNew=()=>supModal(null);ACT.supEdit=(el)=>supModal(itm(el));
ACT.supTest=async(el)=>{await withBusy(el,async()=>{try{const r=await api('POST',`/api/admin/suppliers/${encodeURIComponent(itm(el).id)}/test`);toast(`${r.status.toUpperCase()}: ${r.note||r.message||''}`,r.status==='ok'?'ok':'info',7000);reload()}catch(er){toast(er.message,'err',6000)}})};
ACT.supBal=async(el)=>{await withBusy(el,async()=>{try{const r=await api('POST',`/api/admin/suppliers/${encodeURIComponent(itm(el).id)}/balance`);toast(r.balance!=null?'Supplier balance: '+money(r.balance):(r.note||r.message||'Balance check is not configured for this supplier (Not connected)'),r.balance!=null?'ok':'info',7000);reload()}catch(er){toast(er.message,'err',6000)}})};
ACT.supReveal=async(el)=>{const pw=await askPw('Revealing supplier secrets is audit-logged.');if(!pw)return;try{const r=await api('POST',`/api/admin/suppliers/${encodeURIComponent(itm(el).id)}/reveal`,{password:pw});secretModal('Supplier secrets',[['API key',r.apiKey],['Master key',r.masterKey],['Password',r.password]])}catch(er){toast(er.message,'err')}};
ACT.supDel=async(el)=>{const s=itm(el);if(await confirmDlg('Delete supplier',`Delete <b>${esc(s.name)}</b>? Its PID mappings will stop working.`,{danger:true})){try{await api('DELETE','/api/admin/suppliers/'+encodeURIComponent(s.id));done('Deleted');reload()}catch(er){toast(er.message,'err')}}};
ACT.supLogs=async()=>{const r=await api('GET','/api/admin/supplier-logs?size=50');modal(table(['Date','Supplier','Action','OK','Detail'],r.items.map(l=>[`<span class="muted fs12">${dtxt(l.ts)}</span>`,esc(l.supplierId),esc(l.action||''),l.ok?'<span class="badge ok">OK</span>':'<span class="badge err">FAIL</span>',`<span class="muted fs12">${esc(l.message||l.error||'')}</span>`]),{empty:'No supplier calls yet'}),{title:'Supplier request logs',size:'xl'})};

/* ================= Payment gateways ================= */
V.gateways=async(c)=>{const [r,p]=await Promise.all([api('GET','/api/admin/gateways'),api('GET','/api/admin/payments?size=15')]);A.items.gw=r.gateways;A.gwPresets=r.presets;A.gwPub=r.publicUrl;A.items.pay=p.items;
  c.innerHTML=`<div class="view">${head('Payment Gateways','FAM Gateway, ZapUPI or any gateway. Higher priority is tried first; failures fall back automatically.',`<button class="btn primary" data-act="gwNew">${ico('plus','sm')} Add gateway</button>`)}${r.gateways.length?`<div class="pgrid" style="margin-bottom:16px">${r.gateways.map((g,i)=>`<div class="card pcard"><div class="top"><div class="nm trunc">${esc(g.name)}</div>${statusBadge(g.enabled?(g.configured?stTxt(g.status):'NOT_CONFIGURED'):'INACTIVE')}</div>${g.needsDocs?`<div class="alert warn">${ico('alert')}<div><b>Not configured</b> — needs the provider’s official docs (base URL, create/verify endpoints, response fields) before it can be enabled.</div></div>`:''}<dl class="kv"><dt>Base URL</dt><dd class="mono fs12">${esc(g.baseUrl||'—')}</dd><dt>Create</dt><dd class="mono fs12">${esc(g.createMethod)} ${esc(g.createEndpoint||'—')}</dd><dt>Verify</dt><dd class="mono fs12">${esc(g.verifyMethod)} ${esc(g.verifyEndpoint||'—')}</dd><dt>API key</dt><dd class="mono">${esc(g.apiKeyMask||'not set')}</dd><dt>Limits</dt><dd>${money(g.min)} – ${money(g.max)}</dd><dt>Priority</dt><dd>${g.priority}</dd><dt>Stats</dt><dd>${g.stats.created} created • <span class="ok">${g.stats.paid} paid</span> • <span class="err">${g.stats.failed} failed</span></dd><dt>Webhook</dt><dd class="mono fs12">${esc((A.gwPub||location.origin)+g.webhookPath)}</dd></dl>${g.statusNote?`<div class="hint">${esc(g.statusNote)}</div>`:''}<div class="row wrap gap6">${abtn('gwEdit','Edit','edit','',{k:'gw',i})}${abtn('gwTest','Test','zap','',{k:'gw',i})}${abtn('gwReveal','','eye','',{k:'gw',i})}${abtn('gwDel','','trash','danger',{k:'gw',i})}</div></div>`).join('')}</div>`:`<div class="card" style="margin-bottom:16px">${emptyBox('zap','No gateways yet')}</div>`}
  <div class="card"><div class="card-h">${ico('receipt')}<h3>Payment attempts</h3><div class="sp"></div><button class="btn sm" data-go="allpay">All payments</button></div>${payTable(p.items)}</div></div>`};
const payTable=(items)=>table(['ID','User','Gateway','Amount','Status','Reference','Date',''],items.map((p,i)=>[mini(p.id),esc(p.username),esc(p.gatewayName||''),money(p.amount),statusBadge(p.status)+(p.note?`<div class="muted fs12">${esc(p.note)}</div>`:''),mini(p.reference||'—'),`<span class="muted fs12">${dtxt(p.createdAt)}</span>`,['pending','mismatch','review'].includes(p.status)?rowBtns('pay',i,[['payRe','Recheck','refresh'],...(can('wallet')?[['payOk','Approve','check','ok']]:[])]):'']),{empty:'No payments yet'});
ACT.gwNew=()=>gwModal(null);ACT.gwEdit=(el)=>gwModal(itm(el));
function gwModal(g){const isNew=!g;const P=A.gwPresets;g=g||{preset:'zapupi',enabled:false,priority:100,min:1,max:50000,...P.zapupi};const pr=g.params||{},rs=g.resp||{};
  const m=modal(`<div class="fgrid">${fld('name','Gateway name',g.name||'',{req:true,ph:'ZapUPI / FAM Gateway'})}${fld('preset','Preset',g.preset,{type:'select',opts:Object.entries(P).map(([k,v])=>[k,v.label])})}${fld('baseUrl','Base URL',g.baseUrl||'',{ph:'https://famgateway.in',span:true})}${fld('createEndpoint','Create-order endpoint',g.createEndpoint||'',{ph:'/path'})}${fld('createMethod','Create method',g.createMethod||'GET',{type:'select',opts:['GET','POST']})}${fld('verifyEndpoint','Verify endpoint',g.verifyEndpoint||'',{ph:'/path'})}${fld('verifyMethod','Verify method',g.verifyMethod||'GET',{type:'select',opts:['GET','POST']})}${fld('apiKey','API key / token','',{type:'password',ph:g.apiKeyMask?'Saved — leave empty to keep':''})}${fld('webhookSecret','Webhook secret (optional)','',{type:'password',ph:g.webhookSecretSet?'Saved — leave empty to keep':'',hint:'Used to verify webhook signatures only if the provider documents one'})}${fld('min','Min amount ₹',g.min,{type:'number',step:'0.01'})}${fld('max','Max amount ₹',g.max,{type:'number',step:'0.01'})}${fld('priority','Priority (1 = first)',g.priority,{type:'number',min:1})}${fld('expiresInSec','Order expiry (sec)',g.expiresInSec||300,{type:'number'})}${fld('enabled','Enabled',!!g.enabled,{type:'check'})}</div>
  <details style="margin-top:14px"><summary class="fw6" style="cursor:pointer;color:var(--accent)">Request &amp; response mapping (copy from official docs)</summary><div class="fgrid" style="margin-top:12px">${['apiKey','amount','name','phone','redirect','orderId'].map(k=>fld('p_'+k,'Param: '+k,pr[k]||'')).join('')}${['okPath','okValue','orderIdPath','checkoutPath','amountPath','payablePath','messagePath','statusPath','paidValues','expiredValues','unauthValues','verifyAmountPath','utrPath'].map(k=>fld('r_'+k,'Resp: '+k,rs[k]||'')).join('')}${fld('webhookHeader','Webhook signature header',g.webhookHeader||'',{hint:'e.g. the header name the provider documents'})}${fld('webhookOrderIdPath','Webhook order-id path',g.webhookOrderIdPath||'')}</div></details><div class="alert warn" style="margin-top:14px">${ico('info')}<div>Balance is credited only after the server verifies the payment with the provider. A gateway cannot be enabled until it is fully configured.</div></div>`,{title:isNew?'Add gateway':'Edit '+esc(g.name),size:'lg',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Save gateway</button>'});
  $('#f_preset',m.el).addEventListener('change',e=>{const p=P[e.target.value];if(!p)return;['baseUrl','createEndpoint','verifyEndpoint','createMethod','verifyMethod','expiresInSec'].forEach(k=>{const i=$('#f_'+k,m.el);if(i&&p[k]!=null)i.value=p[k]});Object.entries(p.params||{}).forEach(([k,v])=>{const i=$('#f_p_'+k,m.el);if(i)i.value=v});Object.entries(p.resp||{}).forEach(([k,v])=>{const i=$('#f_r_'+k,m.el);if(i)i.value=v})});
  m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;const v=readF(m.el);const params={},resp={};Object.keys(v).forEach(k=>{if(k.startsWith('p_'))params[k.slice(2)]=v[k];if(k.startsWith('r_'))resp[k.slice(2)]=v[k]});const body={...v,params,resp};['apiKey','webhookSecret'].forEach(k=>{if(!body[k])delete body[k]});await withBusy(b,async()=>{try{await api(isNew?'POST':'PUT',isNew?'/api/admin/gateways':'/api/admin/gateways/'+encodeURIComponent(g.id),body);m.close();done('Gateway saved');reload()}catch(er){toast(er.message,'err',8000)}})})}
ACT.gwTest=async(el)=>{await withBusy(el,async()=>{try{const r=await api('POST',`/api/admin/gateways/${encodeURIComponent(itm(el).id)}/test`);toast(`${String(r.status).toUpperCase()}: ${r.note||r.message||''}`,r.status==='ok'?'ok':'info',7000);reload()}catch(er){toast(er.message,'err',6000)}})};
ACT.gwReveal=async(el)=>{const pw=await askPw('Revealing gateway secrets is audit-logged.');if(!pw)return;try{const r=await api('POST',`/api/admin/gateways/${encodeURIComponent(itm(el).id)}/reveal`,{password:pw});secretModal('Gateway secrets',[['API key',r.apiKey],['Webhook secret',r.webhookSecret]])}catch(er){toast(er.message,'err')}};
ACT.gwDel=async(el)=>{const g=itm(el);if(await confirmDlg('Delete gateway',`Delete <b>${esc(g.name)}</b>?`,{danger:true})){try{await api('DELETE','/api/admin/gateways/'+encodeURIComponent(g.id));done('Deleted');reload()}catch(er){toast(er.message,'err')}}};
ACT.payRe=async(el)=>{const p=A.items[el.dataset.k][+el.dataset.i];await withBusy(el,async()=>{try{const r=await api('POST',`/api/admin/payments/${encodeURIComponent(p.id)}/recheck`);toast('Status: '+r.payment.status,'info');rerender()}catch(er){toast(er.message,'err')}})};
ACT.payOk=(el)=>{const p=A.items[el.dataset.k][+el.dataset.i];const m=modal(`<div class="alert warn" style="margin-bottom:12px">${ico('alert')}<div>Manually credit <b>${money(p.amount)}</b> to ${esc(p.username)}. Only do this after you confirmed the money in your bank/provider dashboard.</div></div>${fld('reason','Reason / reference','',{req:true})}`,{title:'Manual approval',footer:'<button class="btn" data-close>Cancel</button><button class="btn ok" data-sv>Credit user</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;const reason=readF(m.el).reason;if(!reason.trim())return toast('Enter a reason','err');await withBusy(b,async()=>{try{await api('POST',`/api/admin/payments/${encodeURIComponent(p.id)}/approve`,{reason});m.close();done('Credited');rerender()}catch(er){toast(er.message,'err')}})})};
V.allpay=(c)=>listPage(c,'allpay',{title:'All payments',path:'/api/admin/payments',ph:'Search id, user, reference…',filters:[{k:'status',label:'All status',opts:['pending','success','failed','expired','cancelled','mismatch','review']}],summary:(r)=>`<div>Received<b class="ok">${money(r.summary.success)}</b></div><div>Pending<b>${money(r.summary.pending)}</b></div>`,cols:['ID','User','Gateway','Amount','Status','Reference','Date',''],row:(p,i)=>[mini(p.id),esc(p.username),esc(p.gatewayName||''),money(p.amount),statusBadge(p.status)+(p.note?`<div class="muted fs12">${esc(p.note)}</div>`:''),mini(p.reference||'—'),`<span class="muted fs12">${dtxt(p.createdAt)}</span>`,['pending','mismatch','review'].includes(p.status)?rowBtns('allpay',i,[['payRe','Recheck','refresh'],...(can('wallet')?[['payOk','Approve','check','ok']]:[])]):'']});
ALLR.push(['allpay','zap','Payments','gateways']);

/* ================= API clients / docs / logs ================= */
const PERM_L={'products.read':'Read products','balance.read':'Read balance','orders.create':'Create orders','orders.read':'Read orders'};
V.apiclients=async(c)=>{const [r,s]=await Promise.all([api('GET','/api/admin/api-clients'),api('GET','/api/admin/api-stats')]);A.items.cl=r.clients;A.perms=r.permissions;const mx=Math.max(1,...s.clients.flatMap(x=>x.series));
  c.innerHTML=`<div class="view">${head('API Management','Keys act on behalf of one user wallet. Limit permissions, IPs and rate per key.',`<button class="btn primary" data-act="clNew">${ico('plus','sm')} Create API key</button>`)}${s.clients.length?`<div class="card" style="margin-bottom:16px"><div class="card-h">${ico('chart')}<h3>Requests — last 14 days</h3></div>${s.clients.map(x=>`<div style="margin-bottom:12px"><div class="row"><b>${esc(x.name)}</b><span class="muted fs12">${x.total} total • ${x.errors} errors (14d)</span></div><div class="bars" style="height:44px">${x.series.map((v,i)=>`<div style="height:${Math.max(4,v/mx*100)}%" data-tip="${esc(s.days[i])}: ${v}"></div>`).join('')}</div></div>`).join('')}</div>`:''}
  ${table(['Name','User','Key','Permissions','IP allowlist','Rate/min','Requests','Last used','Status',''],r.clients.map((x,i)=>[`<b>${esc(x.name)}</b>${x.selfService?' <span class="badge">SELF</span>':''}`,esc(x.username),mini(x.keyPrefix+'••••'),x.permissions.map(p=>`<span class="badge">${esc(p)}</span>`).join(' '),x.ipAllowlist.length?x.ipAllowlist.map(esc).join(', '):'<span class="muted">any</span>',x.rateLimit,x.requests,`<span class="muted fs12">${dtxt(x.lastUsedAt)}</span>`,x.revokedAt?statusBadge('REVOKED'):statusBadge(x.enabled?'ACTIVE':'INACTIVE'),rowBtns('cl',i,[['clEdit','','edit'],['clReveal','','eye'],['clRegen','','refresh'],['clRevoke','','ban','danger'],['clDel','','trash','danger']])]),{empty:'No API keys yet'})}</div>`};
function clModal(x){const isNew=!x;x=x||{permissions:A.perms,ipAllowlist:[],rateLimit:60,enabled:true};
  const m=modal(`<div class="fgrid">${fld('name','Key name',x.name||'',{req:true})}${isNew?fld('username','User (wallet owner) — username','',{req:true}):`<div class="field"><label>User</label><input class="input" value="${esc(x.username)}" readonly></div>`}${fld('rateLimit','Rate limit (requests / minute)',x.rateLimit,{type:'number',min:1})}${fld('ips','IP allowlist (comma separated, CIDR ok; empty = any)',(x.ipAllowlist||[]).join(', '),{span:true})}</div><div class="lbl" style="margin:14px 0 6px">Permissions</div>${A.perms.map(p=>`<label class="chk"><span class="switch"><input type="checkbox" data-perm="${p}" ${x.permissions.includes(p)?'checked':''}><span></span></span><span class="fw6">${esc(PERM_L[p]||p)}</span><span class="muted fs12 mono">${p}</span></label>`).join('')}${isNew?'':fld('enabled','Enabled',x.enabled,{type:'check'})}`,{title:isNew?'Create API key':'Edit '+esc(x.name),footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Save</button>'});
  m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;const v=readF(m.el);const body={...v,ipAllowlist:v.ips.split(',').map(s=>s.trim()).filter(Boolean),permissions:$$('[data-perm]',m.el).filter(i=>i.checked).map(i=>i.dataset.perm),rateLimit:parseInt(v.rateLimit,10)||60};await withBusy(b,async()=>{try{const r=await api(isNew?'POST':'PUT',isNew?'/api/admin/api-clients':'/api/admin/api-clients/'+encodeURIComponent(x.id),body);m.close();if(isNew)showKey(r.key);else done();reload()}catch(er){toast(er.message,'err',6000)}})})}
const showKey=(k)=>modal(`<div class="alert warn" style="margin-bottom:12px">${ico('alert')}<div>Copy this key now. You can reveal it again later with your admin password.</div></div><div class="keybox"><span>${esc(k)}</span><button class="btn icon sm" data-copy="${esc(k)}">${ico('copy','sm')}</button></div>`,{title:'API key',footer:'<button class="btn primary" data-close>Done</button>'});
ACT.clNew=()=>clModal(null);ACT.clEdit=(el)=>clModal(itm(el));
ACT.clReveal=async(el)=>{const pw=await askPw('Revealing an API key is audit-logged.');if(!pw)return;try{const r=await api('POST',`/api/admin/api-clients/${encodeURIComponent(itm(el).id)}/reveal`,{password:pw});showKey(r.key)}catch(er){toast(er.message,'err')}};
ACT.clRegen=async(el)=>{if(await confirmDlg('Regenerate key','The old key stops working immediately.',{danger:true})){try{const r=await api('POST',`/api/admin/api-clients/${encodeURIComponent(itm(el).id)}/regenerate`);showKey(r.key);reload()}catch(er){toast(er.message,'err')}}};
ACT.clRevoke=async(el)=>{if(await confirmDlg('Revoke key','Requests using this key will be rejected.',{danger:true})){await api('POST',`/api/admin/api-clients/${encodeURIComponent(itm(el).id)}/revoke`);done('Revoked');reload()}};
ACT.clDel=async(el)=>{if(await confirmDlg('Delete key','Permanently delete this API client and its stats?',{danger:true})){await api('DELETE','/api/admin/api-clients/'+encodeURIComponent(itm(el).id));done('Deleted');reload()}};
V.apilogs=(c)=>listPage(c,'apilogs',{title:'API Request Logs',path:'/api/admin/api-logs',search:false,filters:[{k:'status',label:'All results',opts:['ok','error']}],cols:['Time','Client','Method','Path','Status','IP','ms','Order'],row:(l)=>[`<span class="muted fs12">${dtxt(l.ts)}</span>`,esc(l.clientName||l.clientId),`<span class="meth ${esc(l.method)}">${esc(l.method)}</span>`,mini(l.path),l.status<400?`<span class="badge ok">${l.status}</span>`:`<span class="badge err">${l.status}</span>`,mini(l.ip),l.ms??'',mini(l.orderId||'')]});
V.apidocs=async(c)=>{const base=(A.cfg&&A.cfg.backend&&location.origin)||location.origin;const ex=(m,p,b)=>`curl -X ${m} "${base}${p}" \\\n  -H "Authorization: Bearer ak_YOUR_KEY"${b?` \\\n  -H "Content-Type: application/json" \\\n  -H "Idempotency-Key: $(uuidgen)" \\\n  -d '${b}'`:''}`;
  const E=[['GET','/api/v1/products','products.read','List products with PID, duration, price (user or reseller price depending on key owner), stock and availability. Query: ?pid=151 &category=ANDROID',null,'{ "ok": true, "count": 1, "products": [{ "pid": "151", "name": "BALA MODS 151", "category": "ANDROID", "status": "ACTIVE", "plans": [{ "plan_id": "…", "duration": "1 HOUR", "price": 15, "currency": "INR", "delivery": "AUTO API", "stock": null, "available": true }] }] }'],
  ['GET','/api/v1/balance','balance.read','Wallet balance of the key owner.',null,'{ "ok": true, "username": "reseller", "role": "Reseller", "balance": 1500, "currency": "INR" }'],
  ['POST','/api/v1/order','orders.create','Place an order. Wallet is debited server-side; failed deliveries are refunded automatically. Send Idempotency-Key to avoid duplicates.','{"pid":"151","duration":"1 HOUR","quantity":1}','{ "ok": true, "order_id": "ORD-…", "status": "delivered", "pid": "151", "duration": "1 HOUR", "quantity": 1, "unit_price": 10, "total": 10, "keys": ["XXXX-XXXX"], "balance": 1490 }'],
  ['GET','/api/v1/order/{order_id}','orders.read','Fetch one of your orders.',null,'{ "ok": true, "order_id": "ORD-…", "status": "delivered", "keys": ["…"] }'],
  ['GET','/api/v1/orders','orders.read','List your orders. Query: ?page=1&limit=20&status=delivered',null,'{ "ok": true, "total": 3, "page": 1, "limit": 20, "orders": [ … ] }']];
  c.innerHTML=`<div class="view">${head('API Documentation','REST API v1 — every route below is live and served by this backend')}<div class="grid g2" style="margin-bottom:16px"><div class="card"><div class="card-h">${ico('lock')}<h3>Authentication</h3></div><p class="muted fs13">Send the key in the <span class="mono">Authorization: Bearer ak_…</span> header (or <span class="mono">X-API-Key</span>). Keys are created in <a href="#/apiclients">API Management</a> or by Resellers in their panel.</p></div><div class="card"><div class="card-h">${ico('shield')}<h3>Limits &amp; errors</h3></div><p class="muted fs13">Per-key rate limit (see <span class="mono">X-RateLimit-*</span> headers, HTTP 429 + <span class="mono">Retry-After</span>), optional IP allowlist, permissions per key. Errors: <span class="mono">{ "ok": false, "error": "message", "code": "…" }</span> with HTTP 400/401/402/403/404/409/429/5xx.</p></div></div>${E.map(e=>`<div class="card" style="margin-bottom:14px"><div class="row wrap"><span class="meth ${e[0]}">${e[0]}</span><b class="mono">${esc(e[1])}</b><span class="badge">${esc(e[2])}</span></div><p class="muted fs13" style="margin:8px 0">${esc(e[3])}</p><div class="lbl">Request</div><div class="code" style="margin:6px 0 10px">${esc(ex(e[0],e[1].replace('{order_id}','ORD-123'),e[4]))}</div><div class="lbl">Response</div><div class="code" style="margin-top:6px">${esc(e[5])}</div></div>`).join('')}</div>`};

/* ================= Telegram ================= */
V.telegram=async(c)=>{const r=(await api('GET','/api/admin/telegram')).settings;const n=r.notify;
  c.innerHTML=`<div class="view">${head('Telegram Bot','The bot token is stored encrypted on the server and is never sent to any browser')}<div class="grid g2"><div class="card"><div class="card-h">${ico('send')}<h3>Settings</h3>${statusBadge(r.enabled?(r.status==='ok'?'CONNECTED':String(r.status).toUpperCase()):'NOT_CONNECTED')}</div><form id="tgForm" class="col">${fld('enabled','Enable Telegram notifications',r.enabled,{type:'check'})}${fld('token','Bot token','',{type:'password',ph:r.tokenSet?'Saved — leave empty to keep':'Paste token from @BotFather'})}${fld('botUsername','Bot username',r.botUsername,{ph:'my_bot'})}${fld('adminChatId','Admin chat ID',r.adminChatId,{hint:'Your numeric chat id / channel id for admin alerts'})}<div class="lbl">Send notifications for</div>${[['user','User alerts'],['order','Orders'],['payment','Payments'],['admin','Admin alerts'],['delivery','Deliveries'],['api','API requests']].map(([k,l])=>`<label class="chk"><span class="switch"><input type="checkbox" data-nt="${k}" ${n[k]?'checked':''}><span></span></span><span>${l}</span></label>`).join('')}<button class="btn primary" type="submit">Save settings</button></form></div>
  <div class="card"><div class="card-h">${ico('zap')}<h3>Actions</h3></div><div class="col"><button class="btn" data-act="tgTest">${ico('send','sm')} Send test message</button><button class="btn" data-act="tgHook">${ico('link','sm')} Set webhook</button><div class="hint">Webhook: ${r.webhookSet?'<span class="ok">set</span> — '+esc(r.webhookUrl):'not set. Requires PUBLIC_URL (HTTPS) in the backend .env.'}</div>${r.lastError?`<div class="alert err">${ico('alert')}<div>${esc(r.lastError)}</div></div>`:''}<div class="alert info">${ico('info')}<div>Users link their own account from <b>Telegram</b> in their panel with a one-time code.</div></div></div></div></div></div>`};
document.addEventListener('submit',async e=>{if(e.target.id!=='tgForm')return;e.preventDefault();const f=readF(e.target);const notify={};$$('[data-nt]',e.target).forEach(i=>notify[i.dataset.nt]=i.checked);const body={...f,notify};if(!body.token)delete body.token;await withBusy($('button[type=submit]',e.target),async()=>{try{await api('PUT','/api/admin/telegram',body);done('Telegram settings saved');reload()}catch(er){toast(er.message,'err')}})});
ACT.tgTest=async(el)=>{await withBusy(el,async()=>{try{const r=await api('POST','/api/admin/telegram/test');toast(r.ok===false?(r.error||'Failed'):'Test message sent','ok')}catch(er){toast(er.message,'err',6000)}reload()})};
ACT.tgHook=async(el)=>{await withBusy(el,async()=>{try{await api('POST','/api/admin/telegram/webhook');done('Webhook set');reload()}catch(er){toast(er.message,'err',6000)}})};

/* ================= Media / branding ================= */
async function uploadFile(file){const r=await fetch(API_BASE+'/api/admin/media/upload?name='+encodeURIComponent(file.name),{method:'PUT',headers:{Authorization:'Bearer '+A.token,'Content-Type':file.type||'application/octet-stream'},body:file});const j=await r.json().catch(()=>({}));if(!r.ok||j.ok===false)throw new Error(j.error||'Upload failed');return j.item}
const mItem=(m,i,pick)=>`<div class="mitem"><div class="pv">${m.kind==='video'?`<video src="${esc(safeUrl(m.url))}" muted preload="metadata"></video>`:`<img src="${esc(safeUrl(m.url))}" alt="" loading="lazy">`}</div><div class="in"><div class="trunc fw6">${esc(m.name)}</div><div class="muted">${m.kind}${m.size?' • '+(m.size/1024).toFixed(0)+' KB':''}${m.external?' • link':''}</div><div class="row gap6 wrap" style="margin-top:8px">${pick?`<button class="btn sm primary" data-pickok="${esc(m.url)}">Use</button>`:`${abtn('mdUse','Use as…','link','',{k:'media',i})}${abtn('mdCopy','','copy','',{k:'media',i})}${abtn('mdDel','','trash','danger',{k:'media',i})}`}</div></div></div>`;
const uploader=()=>`<div class="drop" id="drop" data-act="pickFile">${ico('upload','xl')}<div class="fw6" style="margin-top:6px">Click or drop files to upload</div><div class="hint">PNG, JPG, WEBP, GIF (≤8 MB) • MP4, WEBM (≤ server limit)</div></div><input type="file" id="fileIn" multiple accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm" class="hidden">`;
function bindUploader(root,done_){const fi=$('#fileIn',root),dr=$('#drop',root);const go=async(files)=>{for(const f of files){try{toast('Uploading '+f.name+'…','info',1500);await uploadFile(f)}catch(er){toast(f.name+': '+er.message,'err',6000)}}done_()};fi.addEventListener('change',()=>go([...fi.files]));['dragover','dragenter'].forEach(ev=>dr.addEventListener(ev,e=>{e.preventDefault();dr.classList.add('on')}));['dragleave','drop'].forEach(ev=>dr.addEventListener(ev,e=>{e.preventDefault();dr.classList.remove('on')}));dr.addEventListener('drop',e=>go([...e.dataTransfer.files]))}
V.media=async(c)=>{const r=await api('GET','/api/admin/media');A.items.media=r.items;c.innerHTML=`<div class="view">${head('Media Manager','Upload images/videos or add external links. Assign them as logo, favicon, banner or product media.',`<button class="btn" data-act="mdUrl">${ico('link','sm')} Add by URL</button>`)}<div class="card" style="margin-bottom:16px">${uploader()}</div>${r.items.length?`<div class="mgrid">${r.items.map((m,i)=>mItem(m,i,false)).join('')}</div>`:`<div class="card">${emptyBox('image','No media yet')}</div>`}</div>`;bindUploader(c,reload)};
ACT.pickFile=(el)=>{$('#fileIn').click()};
ACT.mdUrl=()=>{const m=modal(`<div class="fgrid">${fld('url','URL (https://…)','',{req:true,span:true})}${fld('name','Name','')}${fld('kind','Type','image',{type:'select',opts:['image','video']})}</div>`,{title:'Add media by URL',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Add</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{await api('POST','/api/admin/media/url',readF(m.el));m.close();done('Added');reload()}catch(er){toast(er.message,'err')}})})};
ACT.mdCopy=(el)=>copyText(location.origin+itm(el).url.replace(/^(?!\/)/,'/').replace(/^\/(https?:)/,'$1'));
ACT.mdDel=async(el)=>{if(await confirmDlg('Delete media','Remove this file? Places that use it will show a broken image.',{danger:true})){await api('DELETE','/api/admin/media/'+encodeURIComponent(itm(el).id));done('Deleted');reload()}};
ACT.mdUse=(el)=>{const it=itm(el);const t=it.kind==='video'?[['productVideo','Product video']]:[['logo','Website logo'],['favicon','Favicon'],['banner','Homepage banner'],['productImage','Product image'],['productThumb','Product thumbnail'],['productBanner','Product banner']];
  const m=modal(`${fld('target','Use as',t[0][0],{type:'select',opts:t})}<div id="prodsel" class="hidden" style="margin-top:12px"><div class="field"><label>Product</label><select class="input" data-f="productKey" id="f_productKey"></select></div></div>`,{title:'Assign media',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Assign</button>'});
  const sync=async()=>{const needs=$('#f_target',m.el).value.startsWith('product');$('#prodsel',m.el).classList.toggle('hidden',!needs);if(needs&&!$('#f_productKey',m.el).options.length){const r=await api('GET','/api/admin/products');$('#f_productKey',m.el).innerHTML=r.products.map(p=>`<option value="${esc(p.key)}">${esc(p.name)} (PID ${esc(p.pid)})</option>`).join('')}};$('#f_target',m.el).addEventListener('change',sync);sync();
  m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;const f=readF(m.el);await withBusy(b,async()=>{try{await api('POST','/api/admin/media/assign',{target:f.target,productKey:f.productKey,url:it.url});m.close();done('Assigned')}catch(er){toast(er.message,'err')}})})};
ACT.pickMedia=async(el)=>{const target=document.getElementById(el.dataset.t);const kind=el.dataset.kind;const r=await api('GET','/api/admin/media');const list=r.items.filter(x=>x.kind===kind);A.items.pick=list;const m=modal(`${uploader()}<div class="mgrid" id="pickgrid" style="margin-top:14px">${list.map((x,i)=>mItem(x,i,true)).join('')||'<div class="muted">No '+kind+' files yet — upload one above.</div>'}</div>`,{title:'Media library',size:'lg'});
  bindUploader(m.el,()=>{m.close();ACT.pickMedia(el)});m.ov.addEventListener('click',e=>{const b=e.target.closest('[data-pickok]');if(!b)return;target.value=b.dataset.pickok;m.close()})};
V.branding=async(c)=>{const b=(await api('GET','/api/admin/branding')).branding;const bn=Array.isArray(b.banners)?b.banners:Object.values(b.banners||{});
  c.innerHTML=`<div class="view">${head('Website Branding','Logo, favicon, name, accent colour and homepage banners')}<form id="brForm" class="card col"><div class="fgrid">${fld('siteName','Site name',b.siteName||'ARYAN')}${fld('tagline','Tagline',b.tagline||'')}${mediaField('logoUrl','Logo',b.logoUrl,'image')}${mediaField('faviconUrl','Favicon',b.faviconUrl,'image')}${fld('accent','Accent colour',b.accent||'#00e5ff',{type:'color'})}</div><div class="lbl">Banners (max 10)</div><div id="banners">${bn.map(bannerRow).join('')}</div><div><button type="button" class="btn sm" data-act="bnAdd">${ico('plus','sm')} Add banner</button></div><div class="row"><button class="btn primary" type="submit">Save branding</button></div></form></div>`};
const bannerRow=(x={})=>`<div class="planrow" data-bn style="grid-template-columns:2fr 1.4fr 1fr auto"><div class="row"><input class="input" data-bf="url" placeholder="Image URL" value="${esc(x.url||'')}"><button type="button" class="btn sm" data-act="bnPick">${ico('image','sm')}</button></div><input class="input" data-bf="link" placeholder="Link (optional)" value="${esc(x.link||'')}"><input class="input" data-bf="title" placeholder="Title" value="${esc(x.title||'')}"><button type="button" class="btn icon sm danger" data-act="bnDel">${ico('trash','sm')}</button></div>`;
ACT.bnAdd=()=>$('#banners').insertAdjacentHTML('beforeend',bannerRow());ACT.bnDel=(el)=>el.closest('[data-bn]').remove();
ACT.bnPick=(el)=>{const inp=$('[data-bf=url]',el.closest('[data-bn]'));if(!inp.id)inp.id='bn'+Date.now();ACT.pickMedia({dataset:{t:inp.id,kind:'image'}})};
document.addEventListener('submit',async e=>{if(e.target.id!=='brForm')return;e.preventDefault();const f=readF(e.target);const banners=$$('[data-bn]',e.target).map(r=>({url:$('[data-bf=url]',r).value,link:$('[data-bf=link]',r).value,title:$('[data-bf=title]',r).value,active:true}));await withBusy($('button[type=submit]',e.target),async()=>{try{await api('PUT','/api/admin/branding',{...f,banners});done('Branding saved — live on the user site');}catch(er){toast(er.message,'err')}})});

/* ================= Announcements / maintenance ================= */
V.announcements=async(c)=>{const r=await api('GET','/api/admin/announcements');A.items.an=r.items;c.innerHTML=`<div class="view">${head('Announcements','Shown to users on their dashboard and support page',`<button class="btn primary" data-act="anNew">${ico('plus','sm')} New</button>`)}${table(['Title','Message','Type','Pinned','Status','Date',''],r.items.map((a,i)=>[`<b>${esc(a.title)}</b>`,`<span class="muted">${esc(a.body||'')}</span>`,statusBadge(a.type==='warning'?'PENDING':a.type==='success'?'SUCCESS':'OPEN'),a.pinned?'📌':'',a.active!==false?statusBadge('ACTIVE'):statusBadge('INACTIVE'),`<span class="muted fs12">${dtxt(a.createdAt)}</span>`,rowBtns('an',i,[['anEdit','','edit'],['anDel','','trash','danger']])]),{empty:'No announcements'})}</div>`};
function anModal(a){const m=modal(`<div class="fgrid">${fld('title','Title',a?a.title:'',{req:true,span:true})}${fld('body','Message',a?a.body:'',{type:'textarea',span:true})}${fld('type','Type',a?a.type:'info',{type:'select',opts:['info','warning','success']})}${fld('pinned','Pinned',a&&a.pinned,{type:'check'})}${fld('active','Active',a?a.active!==false:true,{type:'check'})}</div>`,{title:a?'Edit announcement':'New announcement',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Save</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{await api('POST','/api/admin/announcements',{...readF(m.el),id:a?a.id:undefined});m.close();done();reload()}catch(er){toast(er.message,'err')}})})}
ACT.anNew=()=>anModal(null);ACT.anEdit=(el)=>anModal(itm(el));ACT.anDel=async(el)=>{if(await confirmDlg('Delete announcement','Remove it for all users?',{danger:true})){await api('DELETE','/api/admin/announcements/'+encodeURIComponent(itm(el).id));done('Deleted');reload()}};
V.maintenance=async(c)=>{const r=await api('GET','/api/admin/maintenance');
  c.innerHTML=`<div class="view">${head('Maintenance Mode','Block the whole site or mark single products as MAINTENANCE')}<div class="card" style="margin-bottom:16px"><div class="card-h">${ico('tool')}<h3>Site maintenance</h3>${statusBadge(r.site.enabled?'MAINTENANCE':'ACTIVE')}</div><form id="mtForm" class="col">${fld('enabled','Site is under maintenance (users see a maintenance screen; admin stays available)',r.site.enabled,{type:'check'})}${fld('message','Message shown to users',r.site.message||'',{type:'textarea',rows:2})}<div><button class="btn primary" type="submit">Save</button></div></form></div><div class="card"><div class="card-h">${ico('package')}<h3>Per-product maintenance</h3></div>${table(['NAME','PID ID','Maintenance'],r.products.map(p=>[`<b>${esc(p.name)}</b>`,`<span class="pid">${esc(p.pid)}</span>`,`<label class="switch"><input type="checkbox" data-pm="${esc(p.key)}" ${p.on?'checked':''}><span></span></label>`]),{empty:'No products'})}</div></div>`};
document.addEventListener('submit',async e=>{if(e.target.id!=='mtForm')return;e.preventDefault();await withBusy($('button[type=submit]',e.target),async()=>{try{await api('PUT','/api/admin/maintenance/site',readF(e.target));done('Saved');reload()}catch(er){toast(er.message,'err')}})});
document.addEventListener('change',async e=>{const i=e.target.closest('[data-pm]');if(!i)return;try{await api('PUT','/api/admin/maintenance/product/'+encodeURIComponent(i.dataset.pm),{on:i.checked});toast(i.checked?'Product in maintenance':'Product live','ok',1500)}catch(er){i.checked=!i.checked;toast(er.message,'err')}});

/* ================= Settings / security ================= */
V.settings=async(c)=>{const [s,ad]=await Promise.all([api('GET','/api/admin/settings'),api('GET','/api/admin/admins')]);A.items.adm=ad.roles;const l=s.links,rs=s.reseller;
  c.innerHTML=`<div class="view">${head('Admin Settings','Links, reseller rules and admin roles')}<form id="stForm" class="card col" style="margin-bottom:16px"><div class="card-h">${ico('link')}<h3>Links &amp; text</h3></div><div class="fgrid">${fld('howToBuyUrl','How to buy URL',l.howToBuyUrl||'')}${fld('howToDepositUrl','HOW TO DEPOSIT? URL',l.howToDepositUrl||'')}${fld('telegramUrl','Telegram URL',l.telegramUrl||'')}${fld('joinUrl','Join URL',l.joinUrl||'')}${fld('donateUrl','Donate URL',l.donateUrl||'')}${fld('safetyBalance','Safety balance ₹',l.safetyBalance||'',{type:'number'})}${fld('refTarget','Referral target (auto-Reseller)',l.refTarget||30,{type:'number'})}${fld('binanceText','Alt payment text 1',l.binanceText||'')}${fld('bkashText','Alt payment text 2',l.bkashText||'')}${fld('announcement','Short announcement',l.announcement||'',{span:true})}</div><div class="card-h" style="margin-top:10px">${ico('crown')}<h3>Reseller &amp; API</h3></div><div class="fgrid">${fld('r_enabled','Allow self-upgrade to Reseller',rs.enabled,{type:'check'})}${fld('r_min','Minimum wallet balance ₹',rs.minBalance,{type:'number'})}${fld('r_pct','Referral commission %',rs.commissionPct,{type:'number',step:'0.1'})}${fld('a_self','Resellers can create their own API key',s.api.userSelfServe,{type:'check'})}</div><div><button class="btn primary" type="submit">Save settings</button></div></form>
  <div class="card"><div class="card-h">${ico('shield')}<h3>Admin roles</h3><div class="sp"></div><button class="btn sm primary" data-act="admNew">${ico('plus','sm')} Add admin</button></div><div class="hint" style="margin-bottom:10px">Super admins come from <span class="mono">ADMIN_EMAILS</span> in the backend .env: ${ad.envAdmins.map(esc).join(', ')||'(none)'} • Auth mode: <b>${esc(ad.mode)}</b></div>${table(['Email','Role','Added by',''],ad.roles.map((r,i)=>[esc(r.email),statusBadge(r.role.toUpperCase()),esc(r.addedBy||''),rowBtns('adm',i,[['admDel','','trash','danger']])]),{empty:'No additional admins'})}</div></div>`};
document.addEventListener('submit',async e=>{if(e.target.id!=='stForm')return;e.preventDefault();const f=readF(e.target);const links={};['howToBuyUrl','howToDepositUrl','telegramUrl','joinUrl','donateUrl','safetyBalance','refTarget','binanceText','bkashText','announcement'].forEach(k=>links[k]=f[k]);await withBusy($('button[type=submit]',e.target),async()=>{try{await api('PUT','/api/admin/settings',{links,reseller:{enabled:f.r_enabled,minBalance:f.r_min,commissionPct:f.r_pct},api:{userSelfServe:f.a_self}});done('Settings saved')}catch(er){toast(er.message,'err')}})});
ACT.admNew=()=>{const m=modal(`<div class="fgrid">${fld('email','Admin email','',{type:'email',req:true})}${fld('role','Role','support',{type:'select',opts:['manager','finance','support']})}</div><div class="hint" style="margin-top:8px">They sign in with the same auth mode as you (Firebase Auth or local).</div>`,{title:'Add admin',footer:'<button class="btn" data-close>Cancel</button><button class="btn primary" data-sv>Add</button>'});m.ov.addEventListener('click',async e=>{const b=e.target.closest('[data-sv]');if(!b)return;await withBusy(b,async()=>{try{await api('POST','/api/admin/admins',readF(m.el));m.close();done('Added');reload()}catch(er){toast(er.message,'err')}})})};
ACT.admDel=async(el)=>{const r=itm(el);if(await confirmDlg('Remove admin',`Remove ${esc(r.email)}?`,{danger:true})){await api('DELETE','/api/admin/admins/'+encodeURIComponent(r.key));done('Removed');reload()}};
V.security=async(c)=>{const [r,au]=await Promise.all([api('GET','/api/admin/security'),api('GET','/api/admin/audit?size=25')]);
  c.innerHTML=`<div class="view">${head('Security Settings','Checklist, session control and the audit trail')}<div class="grid g2" style="margin-bottom:16px"><div class="card"><div class="card-h">${ico('shield')}<h3>Security checklist</h3></div>${r.checks.map(k=>`<div class="chk">${ico(k.ok?'checkc':'alert')}<div class="sp"><div class="fw6 ${k.ok?'':'warn'}">${esc(k.label)}</div>${!k.ok&&k.hint?`<div class="hint">${esc(k.hint)}</div>`:''}</div>${k.ok?'<span class="badge ok">OK</span>':'<span class="badge warn">TODO</span>'}</div>`).join('')}</div><div class="card"><div class="card-h">${ico('lock')}<h3>Actions</h3></div><div class="col"><button class="btn" data-act="hashLegacy">${ico('key','sm')} Hash legacy passwords (${r.legacyPlaintext} plain-text)</button><button class="btn danger" data-act="adminLogoutAll">${ico('logout','sm')} Logout all admin sessions</button><div class="hint">Admin IP allow-list: ${r.ipAllowlist.length?r.ipAllowlist.map(esc).join(', '):'not set'}</div></div></div></div><div class="card"><div class="card-h">${ico('list')}<h3>Audit log</h3></div>${table(['Time','Admin','Action','Target','Detail','IP'],au.items.map(a=>[`<span class="muted fs12">${dtxt(a.ts)}</span>`,esc(a.email),`<span class="badge info">${esc(a.action)}</span>`,mini(a.target),`<span class="muted fs12">${esc(a.detail)}</span>`,mini(a.ip)]),{empty:'No entries'})}</div></div>`};
ACT.hashLegacy=async(el)=>{if(await confirmDlg('Hash legacy passwords','All remaining plain-text passwords will be hashed and the plain text removed. Users keep their current passwords.')){const r=await api('POST','/api/admin/security/hash-legacy');done(`${r.hashed} password(s) hashed`);reload()}};
ACT.adminLogoutAll=async()=>{if(await confirmDlg('Logout all admins','Every admin session (including yours) ends.',{danger:true})){await api('POST','/api/admin/security/logout-all');A.token='';store.del('aryan_admin_token');A.me=null;showLogin()}};

/* ================= global events ================= */
document.addEventListener('click',async e=>{const t=e.target;let el;
  if((el=t.closest('[data-copy]'))){copyText(el.dataset.copy);return}
  if((el=t.closest('[data-go]'))){location.hash='#/'+el.dataset.go;return}
  if(!(el=t.closest('[data-act]')))return;const a=el.dataset.act;
  try{switch(a){
    case'reload':location.reload();return;case'openNav':$('#side').classList.add('open');$('#scrim').classList.add('show');return;case'closeNav':$('#side').classList.remove('open');$('#scrim').classList.remove('show');return;
    case'accent':applyAccent((parseInt(store.get('aryan_accent')||'0',10)||0)+1);return;
    case'logout':A.token='';store.del('aryan_admin_token');A.me=null;location.hash='';showLogin();return;
    case'lpRefresh':if(A.lpPaint)A.lpPaint();return;
    case'pg':{const st=A.lp[el.dataset.k];st.page=Math.max(1,st.page+parseInt(el.dataset.d,10));A.lpPaint();return}
  }
  if(ACT[a])await ACT[a](el)}catch(er){toast(er.message||'Something went wrong','err',6000)}});
boot();
